import { useEffect, useMemo, useRef, useState } from 'react'
import { createClient } from '@supabase/supabase-js'
import { Activity, Blocks, ClipboardList, ArrowRight, BarChart3, BookOpen, BrainCircuit, BriefcaseBusiness, CalendarDays, CheckCircle2, ChevronRight, CircleHelp, Code2, Coins, ExternalLink, GraduationCap, Headphones, LayoutDashboard, LogOut, Menu, MessageCircle, Moon, Plus, Rocket, Search, Send, ShoppingBag, ShieldAlert, ShieldCheck, Sparkles, Sun, Target, Ticket, Trash2, TrendingUp, Users, Video, Wallet, X, Cpu, Wifi, Lightbulb, Terminal, Copy, Gauge, Workflow, Play } from 'lucide-react'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY
const supabase = supabaseUrl && supabaseKey ? createClient(supabaseUrl, supabaseKey) : null

const areas = [
  {name:'Inteligência artificial',icon:BrainCircuit,desc:'Use IA para estudar, produzir e automatizar.'},
  {name:'Programação e tecnologia',icon:Code2,desc:'Crie sites, aplicativos e soluções digitais.'},
  {name:'Marketing e vendas',icon:TrendingUp,desc:'Aprenda aquisição, conteúdo e conversão.'},
  {name:'Empreendedorismo',icon:BriefcaseBusiness,desc:'Valide ideias, encontre clientes e construa negócios.'},
  {name:'Finanças e investimentos',icon:Coins,desc:'Entenda dinheiro, risco, mercado e planejamento.'},
  {name:'Carreira e habilidades',icon:GraduationCap,desc:'Desenvolva competências e monte seu portfólio.'}
]
const goals = ['Conseguir meu primeiro trabalho ou cliente','Criar uma fonte de renda','Abrir ou melhorar um negócio','Aprender tecnologia e IA','Organizar minhas finanças','Explorar possibilidades e descobrir meu caminho']
const timeOptions = ['Até 30 minutos','30 a 60 minutos','1 a 2 horas','Mais de 2 horas']
const SUPPORT_WHATSAPP = '5563992342186'
const SUPPORT_EMAIL = 'ALEFSOARESVP@GMAIL.COM'

function App(){
  const [session,setSession]=useState(null),[profile,setProfile]=useState(null),[isAdmin,setIsAdmin]=useState(false)
  const [courses,setCourses]=useState([]),[lessons,setLessons]=useState([]),[tools,setTools]=useState([]),[affiliateProducts,setAffiliateProducts]=useState([])
  const [page,setPage]=useState('home'),[selectedCourse,setSelectedCourse]=useState(null),[selectedLesson,setSelectedLesson]=useState(null)
  const [loading,setLoading]=useState(true),[authMode,setAuthMode]=useState('login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[fullName,setFullName]=useState(''),[notice,setNotice]=useState('')
  const [search,setSearch]=useState(''),[mobileMenu,setMobileMenu]=useState(false),[chatOpen,setChatOpen]=useState(false),[chatInput,setChatInput]=useState(''),[chatMessages,setChatMessages]=useState([]),[chatBusy,setChatBusy]=useState(false)
  const [answers,setAnswers]=useState({goal:'',areas:[],time:'',experience:'',known_platforms:'',current_activity:'',six_month_goal:'',personal_vision:'',guardian_email:'',age_group:'unverified'})
  const [saving,setSaving]=useState(false),[activationCode,setActivationCode]=useState(''),[signupAgeGroup,setSignupAgeGroup]=useState('adult'),[guardianEmail,setGuardianEmail]=useState('')
  const [darkMode,setDarkMode]=useState(false)
  const [labInitialTab,setLabInitialTab]=useState('chain'),[selectedPracticalLab,setSelectedPracticalLab]=useState('esp32'),[chatConversationId,setChatConversationId]=useState(null)
  useEffect(()=>{setDarkMode(window.localStorage.getItem('azelf-theme')==='dark')},[])
  useEffect(()=>{const invite=new URLSearchParams(window.location.search).get('invite');if(invite){setActivationCode(invite.toUpperCase());setAuthMode('signup');setPage('auth')}},[])
  useEffect(()=>{const url=new URL(window.location.href);const source=url.searchParams.get('utm_source');if(source&&source.includes('.')){url.searchParams.delete('utm_source');window.history.replaceState(window.history.state,'',url.pathname+url.search+url.hash)}},[])
  useEffect(()=>{window.localStorage.setItem('azelf-theme',darkMode?'dark':'light')},[darkMode])
  useEffect(()=>{ if(!supabase){setLoading(false);return} supabase.auth.getSession().then(({data})=>setSession(data.session)); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s)); return ()=>subscription.unsubscribe() },[])
  useEffect(()=>{ if(session?.user) loadWorkspace(); else {setProfile(null);setIsAdmin(false);setCourses([]);setLessons([]);setTools([]);loadPublicCatalog()} },[session])
  async function loadWorkspace(){
    setLoading(true); const uid=session.user.id
    const [p,r,c,l,t,ap]=await Promise.all([
      supabase.from('profiles').select('*').eq('id',uid).maybeSingle(),
      supabase.from('user_roles').select('role').eq('user_id',uid).maybeSingle(),
      supabase.from('courses').select('*').order('sort_order'),
      supabase.from('lessons').select('*').order('sort_order'),
      supabase.from('tools').select('*').order('sort_order'),
      supabase.from('affiliate_products').select('*').eq('is_published',true).order('sort_order')
    ])
    setProfile(p.data||null); setIsAdmin(r.data?.role==='admin'); setCourses(c.data||[]); setLessons(l.data||[]); setTools(t.data||[]); setAffiliateProducts(ap.data||[]); setLoading(false)
  }
  async function loadPublicCatalog(){setLoading(true);try{const [t,a]=await Promise.all([supabase.from('tools').select('*').eq('is_published',true).eq('adult_only',false).order('sort_order'),supabase.from('affiliate_products').select('*').eq('is_published',true).eq('adult_only',false).order('sort_order')]);setTools(t.data||[]);setAffiliateProducts(a.data||[])}catch(error){console.warn('public catalog unavailable',error)}finally{setLoading(false)}}
  async function refreshLearningContent(){const [c,l,t]=await Promise.all([supabase.from('courses').select('*').order('sort_order'),supabase.from('lessons').select('*').order('sort_order'),supabase.from('tools').select('*').order('sort_order')]);setCourses(c.data||[]);setLessons(l.data||[]);setTools(t.data||[])}
  async function trackActivity(event_type,entity_type=null,entity_id=null,metadata={}){if(!session?.user?.id)return;try{await supabase.from('learning_activity').insert({user_id:session.user.id,event_type,entity_type,entity_id,metadata})}catch(error){console.warn('activity log unavailable',error)}}
  const lastLoginTracked=useRef(null)
  useEffect(()=>{if(session?.user?.id&&lastLoginTracked.current!==session.user.id){lastLoginTracked.current=session.user.id;trackActivity('login','session',session.user.id,{source:'web_app'})}if(!session?.user?.id)lastLoginTracked.current=null},[session?.user?.id])

  const visibleCourses=useMemo(()=>courses.filter(c=>c.is_published&&(profile?.age_group==='adult'||!c.adult_only)&&(!search||[c.title,c.description,c.category].join(' ').toLowerCase().includes(search.toLowerCase()))),[courses,profile,search])
  async function authenticate(e){
    e.preventDefault();setNotice('');setSaving(true);
    try {
      if(authMode==='signup'){
        if(!activationCode.trim()) throw new Error('Informe seu código de ativação.');
        if(password.length<10) throw new Error('Use uma senha com pelo menos 10 caracteres.');
        if(signupAgeGroup==='minor'&&!guardianEmail.trim()) throw new Error('Informe o e-mail do responsável legal.');
        const {data,error}=await supabase.functions.invoke('activate-account',{body:{
          code:activationCode,email,password,full_name:fullName,age_group:signupAgeGroup,
          guardian_email:guardianEmail
        }});
        if(error) throw error;
        if(data?.error) throw new Error(data.error);
        if(signupAgeGroup==='minor'){
          setNotice('Conta criada. O acesso ficará pendente até a equipe confirmar o responsável legal. O responsável será contatado conforme o procedimento de validação.');
          setAuthMode('login'); return;
        }
        const login=await supabase.auth.signInWithPassword({email,password});
        if(login.error) throw login.error;
        setNotice('Conta criada e ativada.');
      } else {
        const {error}=await supabase.auth.signInWithPassword({email,password});
        if(error) throw error;
        setNotice('Login realizado.');
      }
    } catch(err) { setNotice(err?.message||'Não foi possível concluir a operação.'); }
    finally { setSaving(false); }
  }
  async function signOut(){await supabase.auth.signOut();setChatConversationId(null);setChatMessages([]);setPage('home')}
  async function saveOnboarding(e){e.preventDefault();setSaving(true);const {error}=await supabase.from('profiles').upsert({id:session.user.id,full_name:fullName||session.user.user_metadata?.full_name||'',age_group:answers.age_group,guardian_email:answers.age_group==='minor'?answers.guardian_email:null,onboarding_completed:answers.age_group!=='minor',access_status:answers.age_group==='minor'?'pending':undefined,guardian_consent_status:answers.age_group==='minor'?'pending':undefined,onboarding_answers:answers},{onConflict:'id'});setSaving(false);if(error)setNotice(error.message);else{await trackActivity('onboarding_completed','profile',session.user.id,{goal:answers.goal,interests:answers.areas});if(answers.age_group==='minor'){setNotice('Diagnóstico recebido. O acesso ficará pendente até a validação do responsável legal.');await loadWorkspace()}else{setNotice('Diagnóstico salvo. Seu plano inicial está pronto.');await loadWorkspace();setPage('dashboard')}}}
  async function toggleProgress(lesson){const {error}=await supabase.from('lesson_progress').upsert({user_id:session.user.id,lesson_id:lesson.id,completed:true,completed_at:new Date().toISOString()},{onConflict:'user_id,lesson_id'});if(error)setNotice('Não foi possível salvar o progresso: '+error.message);else{await trackActivity('lesson_completed','lesson',lesson.id,{title:lesson.title});setNotice('Aula marcada como concluída.')}}
  async function saveLessonProject(lesson,project){const {error}=await supabase.from('student_projects').insert({user_id:session.user.id,course_id:selectedCourse?.id||null,lesson_id:lesson.id,title:project.title,area:selectedCourse?.category||'Projeto da aula',description:project.description,deliverable_url:project.url||null,status:'submitted',submitted_at:new Date().toISOString()});if(error){setNotice('Não foi possível enviar o projeto: '+error.message);return false}await trackActivity('project_created','lesson',lesson.id,{title:project.title});setNotice('Projeto enviado para revisão. Você poderá acompanhar o feedback no painel de aprendizagem.');return true}
  async function askTutor(e){e.preventDefault();if(!chatInput.trim()||!supabase)return;const text=chatInput.trim();setChatInput('');setChatMessages(m=>[...m,{role:'user',content:text}]);setChatBusy(true);await trackActivity('tutor_question',selectedLesson?'lesson':selectedCourse?'course':'general',selectedLesson?.id||selectedCourse?.id||null,{question:text.slice(0,700),course:selectedCourse?.title||null,lesson:selectedLesson?.title||null});try{const {data,error}=await supabase.functions.invoke('ai-tutor',{body:{message:text,conversation_id:chatConversationId,context:{page,lab_name:page==='crypto-lab'?'Laboratório de blockchain, mercado e negócio':page==='practical-lab'?selectedPracticalLab:'',course_title:selectedCourse?.title||'',lesson_title:selectedLesson?.title||'',lesson_summary:selectedLesson?.summary||'',lesson_content:selectedLesson?.content_md||'',learner_goal:profile?.onboarding_answers?.goal||'',learning_interests:(profile?.onboarding_answers?.areas||[]).join(', '),known_platforms:profile?.onboarding_answers?.known_platforms||'',current_activity:profile?.onboarding_answers?.current_activity||'',experience_level:profile?.onboarding_answers?.experience||'',six_month_goal:profile?.onboarding_answers?.six_month_goal||'',personal_vision:profile?.onboarding_answers?.personal_vision||''}}});if(error)throw error;if(data?.conversation_id)setChatConversationId(data.conversation_id);const answer=data?.answer||data?.response||data?.message||'Recebi sua pergunta, mas não encontrei o texto da resposta.';setChatMessages(m=>[...m,{role:'assistant',content:answer}])}catch(err){setChatMessages(m=>[...m,{role:'assistant',content:'Não consegui acessar o tutor agora. Verifique a função ai-tutor e tente novamente.'}])}finally{setChatBusy(false)}}
  const lessonsFor=course=>lessons.filter(l=>l.course_id===course.id&&l.is_published&&(profile?.age_group==='adult'||!l.adult_only))
  if(!supabase)return <SetupScreen/>
  return <div className={darkMode?'app-shell dark-mode':'app-shell'}>
    <header className="topbar"><button className="brand" onClick={()=>setPage(session?'dashboard':'home')}><span className="brand-mark">AZ</span><span>AZELF<small>APRENDER · CRIAR · EVOLUIR</small></span></button>
      <button className="mobile-toggle" onClick={()=>setMobileMenu(!mobileMenu)} aria-label="Menu">{mobileMenu?<X/>:<Menu/>}</button>
      <nav className={mobileMenu?'nav open':'nav'}><button onClick={()=>{setPage(session?'dashboard':'home');setMobileMenu(false)}}>Início</button><button onClick={()=>{setPage('courses');setMobileMenu(false)}}>Aprender</button><button onClick={()=>{setPage('my-projects');setMobileMenu(false)}}>Meus projetos</button><button onClick={()=>{setPage('lab');setMobileMenu(false)}}>Laboratórios</button><button onClick={()=>{setPage('tools');setMobileMenu(false)}}>Ferramentas</button><button onClick={()=>{setPage('affiliates');setMobileMenu(false)}}>Afiliados</button><button onClick={()=>{setPage('income');setMobileMenu(false)}}>Ganhar dinheiro</button><button onClick={()=>{setPage('recommendations');setMobileMenu(false)}}>Recomendações</button>{session&&<button onClick={()=>{setPage('support');setMobileMenu(false)}}>Ajuda</button>}<button onClick={()=>{setChatOpen(true);setMobileMenu(false)}}>Tutor IA</button>{isAdmin&&<button onClick={()=>{setPage('admin');setMobileMenu(false)}}>Admin</button>}</nav>
      <div className="top-actions"><button className="icon-button theme-toggle" onClick={()=>setDarkMode(v=>!v)} title={darkMode?'Ativar tema claro':'Ativar tema escuro'}>{darkMode?<Sun size={18}/>:<Moon size={18}/>}</button>{session?<><span className="user-pill">{isAdmin?'ADMINISTRADOR':profile?.full_name||session.user.email}</span><button className="icon-button" onClick={signOut} title="Sair"><LogOut size={18}/></button></>:<button className="button button-small" onClick={()=>setPage('auth')}>Entrar <ArrowRight size={16}/></button>}</div>
    </header>
    <main>
      {loading?<div className="loading">Carregando sua área de aprendizagem…</div>:!session&&page!=='auth'&&!['lab','practical-lab','crypto-lab','tools','affiliates','income'].includes(page)?<Landing onStart={()=>setPage('auth')}/>:!session&&page==='auth'?<section className="auth-wrap"><div className="auth-card"><span className="eyebrow">SUA PRÓXIMA FASE COMEÇA AQUI</span><h1>{authMode==='login'?'Entre na AZELF':'Crie sua conta'}</h1><p>Aprenda habilidades úteis e transforme conhecimento em projetos reais. Ao usar um convite, informe o mesmo e-mail que o administrador vinculou ao código.</p><form onSubmit={authenticate}>{authMode==='signup'&&<><label>Nome completo<input value={fullName} onChange={e=>setFullName(e.target.value)} required placeholder="Como podemos chamar você?"/></label><label>Código de convite<input value={activationCode} onChange={e=>setActivationCode(e.target.value.toUpperCase())} required placeholder="Código gerado pelo administrador"/></label><label>Faixa etária<select value={signupAgeGroup} onChange={e=>setSignupAgeGroup(e.target.value)}><option value="adult">18 anos ou mais</option><option value="minor">Menos de 18 anos</option></select></label>{signupAgeGroup==='minor'&&<label>E-mail do responsável legal<input type="email" value={guardianEmail} onChange={e=>setGuardianEmail(e.target.value)} required placeholder="responsavel@email.com"/></label>}</>}<label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="voce@email.com"/></label><label>Senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength="10" required placeholder="Mínimo de 10 caracteres"/></label><button className="button button-full" disabled={saving}>{saving?'Aguarde…':authMode==='login'?'Entrar':'Criar conta com convite'}</button></form>{notice&&<p className="notice">{notice}</p>}<button className="text-button" onClick={()=>{setAuthMode(authMode==='login'?'signup':'login');setNotice('')}}>{authMode==='login'?'Tem um código de convite? Criar conta':'Já tem conta? Entrar'}</button></div></section>:profile?.age_group==='minor'&&profile?.access_status!=='active'?<section className="workspace"><div className="panel"><ShieldCheck/><h1>Acesso aguardando responsável</h1><p>Seu cadastro foi recebido. A equipe AZELF precisa validar o consentimento do responsável antes de liberar o conteúdo.</p></div></section>:session&&!profile?.onboarding_completed&&!isAdmin&&!['lab','practical-lab','crypto-lab','tools','affiliates'].includes(page)?<Onboarding answers={answers} setAnswers={setAnswers} fullName={fullName} setFullName={setFullName} save={saveOnboarding} saving={saving} notice={notice}/>:page==='admin'&&isAdmin?<Admin courses={courses} lessons={lessons} tools={tools} profile={profile} refresh={refreshLearningContent}/>:page==='courses'?<Courses courses={visibleCourses} lessonsFor={lessonsFor} openCourse={c=>{trackActivity('course_opened','course',c.id,{title:c.title});setSelectedCourse(c);setPage('course')}} search={search} setSearch={setSearch}/>:page==='course'&&selectedCourse?<Course course={selectedCourse} lessons={lessonsFor(selectedCourse)} openLesson={l=>{trackActivity('lesson_opened','lesson',l.id,{title:l.title,course:selectedCourse.title});setSelectedLesson(l);setPage('lesson')}} back={()=>setPage('courses')}/>:page==='lesson'&&selectedLesson?<Lesson lesson={selectedLesson} course={selectedCourse} back={()=>setPage('course')} complete={()=>toggleProgress(selectedLesson)} ask={()=>setChatOpen(true)} saveProject={saveLessonProject}/>:page==='tools'?<Tools tools={tools} profile={profile} onOpen={name=>trackActivity('tool_opened','tool',null,{name})}/>:page==='affiliates'?<AffiliateProducts products={affiliateProducts} session={session} profile={profile} onOpen={p=>trackActivity('tool_opened','affiliate_product',p.id,{title:p.title,platform:p.platform})}/>:page==='income'?<IncomeHub openCourses={()=>setPage('courses')} openLabs={()=>setPage('lab')} openTools={()=>setPage('tools')} openAffiliates={()=>setPage('affiliates')} openChat={()=>setChatOpen(true)} onStartCourse={()=>{const c=courses.find(x=>x.slug==='renda-digital-na-pratica');if(c){setSelectedCourse(c);setPage('course')}else setPage('auth')}}/>:page==='lab'?<LearningLab openCrypto={tab=>{setLabInitialTab(tab);setPage('crypto-lab')}} openPractical={key=>{setSelectedPracticalLab(key);setPage('practical-lab')}} customLabs={courses.filter(c=>c.is_published&&/laborat[oó]rio|lab/i.test(c.category||'')&&(profile?.age_group==='adult'||!c.adult_only))} openCustomLab={c=>{setSelectedCourse(c);setPage('course')}}/>:page==='crypto-lab'?<CryptoLab back={()=>setPage('lab')} initialTab={labInitialTab}/>:page==='practical-lab'?<PracticalLab lab={selectedPracticalLab} back={()=>setPage('lab')}/>:page==='my-projects'?<MyProjects session={session} openCourses={()=>setPage('courses')}/>:page==='support'?<Support session={session} profile={profile} onTicketCreated={()=>trackActivity('support_requested','support',null,{source:'help_center'})}/>:page==='recommendations'?<Recommendations courses={visibleCourses} profile={profile} products={affiliateProducts} onProductOpen={p=>trackActivity('tool_opened','affiliate_product',p.id,{title:p.title,platform:p.platform})} openCourse={c=>{trackActivity('course_opened','course',c.id,{title:c.title,source:'recommendations'});setSelectedCourse(c);setPage('course')}} openLab={()=>setPage('lab')} openTools={()=>setPage('tools')} openChat={()=>setChatOpen(true)} openCourses={()=>setPage('courses')}/>:page==='dashboard'?<Dashboard session={session} profile={profile} courses={visibleCourses} lessons={lessons} openCourses={()=>setPage('courses')} openChat={()=>setChatOpen(true)} openOnboarding={()=>setPage('onboarding')} openLab={()=>setPage('lab')} openSupport={()=>setPage('support')} openProjects={()=>setPage('my-projects')}/>:page==='onboarding'?<Onboarding answers={answers} setAnswers={setAnswers} fullName={fullName} setFullName={setFullName} save={saveOnboarding} saving={saving} notice={notice}/>:<Dashboard session={session} profile={profile} courses={visibleCourses} lessons={lessons} openCourses={()=>setPage('courses')} openChat={()=>setChatOpen(true)} openOnboarding={()=>setPage('onboarding')} openLab={()=>setPage('lab')} openSupport={()=>setPage('support')}/>}
    </main>
    <nav className="mobile-bottom-nav" aria-label="Navegação principal">
      <button className={['home','dashboard'].includes(page)?'active':''} onClick={()=>setPage(session?'dashboard':'home')}><LayoutDashboard size={19}/><span>Início</span></button>
      {session?<button className={page==='courses'?'active':''} onClick={()=>setPage('courses')}><BookOpen size={19}/><span>Cursos</span></button>:<button className={page==='tools'?'active':''} onClick={()=>setPage('tools')}><BrainCircuit size={19}/><span>IAs</span></button>}
      <button className={['lab','practical-lab','crypto-lab'].includes(page)?'active':''} onClick={()=>setPage('lab')}><Blocks size={19}/><span>Labs</span></button>
      {isAdmin?<button className={page==='admin'?'active':''} onClick={()=>setPage('admin')}><ShieldCheck size={19}/><span>Admin</span></button>:session?<button className={page==='my-projects'?'active':''} onClick={()=>setPage('my-projects')}><ClipboardList size={19}/><span>Projetos</span></button>:<button className={page==='affiliates'?'active':''} onClick={()=>setPage('affiliates')}><ShoppingBag size={19}/><span>Afiliados</span></button>}
    </nav>
    <footer><span>AZELF © {new Date().getFullYear()}</span><span>Conhecimento aplicado. Progresso real.</span><a href={'mailto:'+SUPPORT_EMAIL}>Suporte: {SUPPORT_EMAIL}</a><span>Conteúdo educacional — resultados dependem de prática e contexto.</span></footer>
    {session&&<button className="chat-fab" onClick={()=>setChatOpen(true)} aria-label="Abrir tutor IA"><MessageCircle/><span>Tutor IA</span></button>}
    {chatOpen&&<div className="chat-panel"><div className="chat-head"><div><strong><Sparkles size={17}/> Tutor AZELF</strong><small>Assistente de aprendizagem</small></div><button className="icon-button" onClick={()=>setChatOpen(false)}><X/></button></div><div className="chat-body">{chatMessages.length===0&&<div className="chat-welcome"><BrainCircuit size={28}/><strong>O que você quer aprender ou resolver?</strong><p>Posso explicar conceitos, ajudar com exercícios e orientar seu próximo passo.</p></div>}{chatMessages.map((m,i)=><div key={i} className={'chat-msg '+m.role}>{m.content}</div>)}{chatBusy&&<div className="chat-msg assistant">Pensando…</div>}</div><form className="chat-form" onSubmit={askTutor}><input value={chatInput} onChange={e=>setChatInput(e.target.value)} placeholder="Digite sua pergunta…" /><button className="button" disabled={chatBusy}><ArrowRight/></button></form></div>}
  </div>
}

function SetupScreen(){return <div className="setup"><div className="brand-mark">A</div><h1>AZELF</h1><h2>Configuração de publicação necessária</h2><p>O código está pronto para receber as variáveis públicas do Supabase no Cloudflare Pages:</p><code>VITE_SUPABASE_URL</code><code>VITE_SUPABASE_ANON_KEY</code><p>As chaves secretas da OpenAI permanecem exclusivamente nos Supabase Edge Function Secrets.</p></div>}
function Landing({onStart}){return <><section className="hero"><div className="hero-copy"><span className="eyebrow"><Sparkles size={15}/> CONHECIMENTO QUE VIRA CAPACIDADE</span><h1>Seu próximo passo<br/><em>começa com o que você aprende.</em></h1><p>Aprenda, pratique em laboratórios interativos e transforme habilidades em projetos reais — no seu ritmo, com orientação de IA.</p><div className="hero-buttons"><button className="button" onClick={onStart}>Entrar na AZELF <ArrowRight size={18}/></button><span>Uma jornada que começa com seu objetivo, não com um curso aleatório.</span></div><div className="hero-proof"><div><strong>Aprender</strong><small>Conhecimento aplicado</small></div><div><strong>Experimentar</strong><small>Simulações seguras</small></div><div><strong>Construir</strong><small>Portfólio e renda</small></div></div></div><div className="hero-art hero-3d-stage"><div className="orbit orbit-one"></div><div className="orbit orbit-two"></div><div className="orbit orbit-three"></div><div className="hero-cloud cloud-back"></div><div className="hero-cloud cloud-front"></div><div className="hero-3d-orb"><div className="orb-core"><span>A</span><small>AZELF</small></div><i className="orb-ring ring-a"></i><i className="orb-ring ring-b"></i><i className="orb-glow"></i></div><div className="float-card card-top"><BrainCircuit/> Inteligência artificial</div><div className="float-card card-right"><Blocks/> Blockchain na prática</div><div className="float-card card-bottom"><Target/> Seu plano de evolução</div></div></section><section className="section"><div className="section-heading"><span className="eyebrow">APRENDA E APLIQUE</span><h2>Não fique só assistindo. Construa.</h2><p>Trilhas, desafios, simuladores, tutoria de IA e projetos guiados em uma jornada adaptada à sua realidade.</p></div><div className="area-grid">{areas.map(a=><div className="area-card" key={a.name}><a.icon/><h3>{a.name}</h3><p>{a.desc}</p><ChevronRight/></div>)}</div><div className="landing-lab-promo"><div><span className="eyebrow">LABORATÓRIO INTERATIVO</span><h2>Explore sem arriscar dinheiro real.</h2><p>Entenda blockchain, tokens, carteiras, gráfico, custos e margem usando simulações que deixam cada etapa visível.</p></div><div className="lab-promo-mark"><Blocks size={40}/><span>SIMULAÇÃO</span></div></div></section><section className="quote-band"><span>“O futuro não muda com intenção. Muda com conhecimento aplicado, consistência e ação.”</span><small>AZELF · APRENDER. CRIAR. EVOLUIR.</small></section></>}
function Dashboard({session,profile,courses,lessons,openCourses,openChat,openOnboarding,openLab,openSupport,openProjects}){
  const [completed,setCompleted]=useState(0),[projectCount,setProjectCount]=useState(0),[projectReviewed,setProjectReviewed]=useState(0),[progressLoading,setProgressLoading]=useState(true)
  useEffect(()=>{async function load(){if(!session?.user?.id)return;setProgressLoading(true);const [p,s]=await Promise.all([supabase.from('lesson_progress').select('lesson_id',{count:'exact',head:true}).eq('user_id',session.user.id).eq('completed',true),supabase.from('student_projects').select('id,status').eq('user_id',session.user.id)]);setCompleted(p.count||0);setProjectCount(s.data?.length||0);setProjectReviewed((s.data||[]).filter(x=>['reviewed','needs_changes'].includes(x.status)).length);setProgressLoading(false)}load()},[session?.user?.id])
  const answers=profile?.onboarding_answers||{}
  const interestText=[...(answers.areas||[]),answers.goal||'',answers.skills_available||'',answers.current_activity||''].join(' ').toLowerCase()
  const recommendations=useMemo(()=>{
    const score=(course)=>{
      const hay=(course.title+' '+course.category+' '+course.description).toLowerCase()
      let points=0
      if(/inteligência artificial|automação|ia/.test(interestText)&&/ia|inteligência|automação|prompt/.test(hay))points+=5
      if(/programação|tecnologia|sites/.test(interestText)&&/programação|desenvolvimento|site|projeto/.test(hay))points+=5
      if(/marketing|vendas|clientes|renda|negócio/.test(interestText)&&/marketing|vendas|freelance|negócios|curso|ecommerce/.test(hay))points+=5
      if(/finanças|cripto|trading|mercado/.test(interestText)&&/finanças|cripto|trading|mercado/.test(hay))points+=5
      if(/primeiro trabalho|primeiro cliente|fonte de renda|negócio/.test(answers.goal||'')&&/freelance|projetos|vendas|negócios/.test(hay))points+=4
      if(/portfólio|projeto/.test(hay))points+=2
      return points
    }
    return [...courses].sort((a,b)=>score(b)-score(a)).slice(0,3)
  },[courses,interestText,answers.goal])
  const weeklySteps=[
    {week:'Semana 1',title:'Escolher uma habilidade e entender o problema',detail:'Defina uma pessoa que você pode ajudar e o resultado que ela precisa.'},
    {week:'Semana 2',title:'Praticar com uma ferramenta',detail:'Faça exercícios curtos e documente o processo em vez de apenas consumir aulas.'},
    {week:'Semana 3',title:'Construir uma entrega demonstrável',detail:'Crie um exemplo realista, uma página, um vídeo, uma automação ou um estudo de caso.'},
    {week:'Semana 4',title:'Montar portfólio e validar com alguém',detail:'Mostre o trabalho a uma pessoa, peça feedback e ajuste antes de oferecer como serviço.'}
  ]
  return <section className="workspace"><div className="welcome-row"><div><span className="eyebrow">SUA CENTRAL DE EVOLUÇÃO</span><h1>Olá, {profile?.full_name?.split(' ')[0]||'estudante'}.</h1><p>Seu próximo passo é transformar uma habilidade em algo demonstrável.</p></div><div className="welcome-mark"><Sparkles/></div></div>
    <div className="stats-grid"><Stat label="Trilhas disponíveis" value={courses.length} icon={BookOpen}/><Stat label="Aulas concluídas" value={progressLoading?'…':completed} icon={GraduationCap}/><Stat label="Projetos enviados" value={progressLoading?'…':projectCount} icon={Target}/></div>
    <div className="learner-roadmap panel"><div className="panel-title"><div><span className="eyebrow">SUA JORNADA PERSONALIZADA</span><h2>Um caminho para sair da intenção e chegar à entrega.</h2></div><span className="status-pill active">Baseado no seu diagnóstico</span></div><p className="roadmap-context">{answers.goal?'Objetivo informado: '+answers.goal+'. ':''}{answers.time?'Tempo disponível: '+answers.time+'. ':''}{answers.biggest_blocker?'Vamos considerar sua dificuldade principal: '+answers.biggest_blocker+'.':''}</p><div className="roadmap-courses">{recommendations.map((course,i)=><button className="roadmap-course" key={course.id} onClick={openCourses}><span className="roadmap-number">{i+1}</span><span><strong>{course.title}</strong><small>{course.category} · {course.description}</small></span><ChevronRight size={17}/></button>)}</div><div className="roadmap-weeks">{weeklySteps.map(step=><article key={step.week}><span>{step.week}</span><strong>{step.title}</strong><small>{step.detail}</small></article>)}</div><p className="admin-footnote">O plano é um roteiro inicial, não uma promessa de renda. Ele será mais preciso conforme você enviar projetos e atualizar suas habilidades e objetivos.</p></div>
    <div className="dashboard-grid"><div className="panel panel-main"><div className="panel-title"><div><span className="eyebrow">CONTINUE EVOLUINDO</span><h2>Escolha uma trilha</h2></div><button className="text-button" onClick={openCourses}>Ver todas <ArrowRight size={15}/></button></div>{courses.slice(0,5).map(course=><button className="course-row" key={course.id} onClick={openCourses}><span className="course-icon"><BookOpen/></span><span><strong>{course.title}</strong><small>{course.category} · {course.description||'Aprenda e pratique'}</small></span><ChevronRight/></button>)}</div><div className="panel"><span className="eyebrow">SUA CAIXA DE FERRAMENTAS</span><h2>Aprender fazendo.</h2><p>Experimente um laboratório de blockchain, simulação de mercado e cálculo de margem sem colocar dinheiro real em risco.</p><button className="button button-full" onClick={openLab}><Blocks size={17}/> Abrir laboratórios</button><button className="outline-button button-full" onClick={openChat}><MessageCircle size={17}/> Perguntar ao tutor</button><button className="outline-button button-full" onClick={openProjects}><ClipboardList size={17}/> Acompanhar meus projetos {projectReviewed>0&&<span className="status-pill active">{projectReviewed} feedbacks</span>}</button><button className="outline-button button-full" onClick={openSupport}><Headphones size={17}/> Pedir ajuda</button><button className="text-button" onClick={openOnboarding}>Atualizar meu diagnóstico</button></div></div></section>}
function Stat({label,value,icon:Icon}){return <div className="stat-card"><Icon/><strong>{value}</strong><small>{label}</small></div>}
function Courses({courses,lessonsFor,openCourse,search,setSearch}){return <section className="workspace"><div className="section-heading left"><span className="eyebrow">BIBLIOTECA AZELF</span><h1>Trilhas de aprendizagem</h1><p>Escolha uma habilidade, estude e aplique em um projeto.</p></div><div className="search-box"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por curso, tema ou habilidade…"/></div><div className="course-grid">{courses.map(c=><button className="course-card" key={c.id} onClick={()=>openCourse(c)}><div className="course-card-top"><span className="course-icon"><BookOpen/></span><span>{c.category}</span></div><h3>{c.title}</h3><p>{c.description}</p><div className="course-card-bottom"><span>{lessonsFor(c).length} aulas</span><span>Explorar <ArrowRight size={15}/></span></div></button>)}</div>{courses.length===0&&<p className="empty">Nenhuma trilha encontrada para essa busca.</p>}</section>}
function Course({course,lessons,openLesson,back}){return <section className="workspace"><button className="back-button" onClick={back}>← Todas as trilhas</button><div className="section-heading left"><span className="eyebrow">{course.category}</span><h1>{course.title}</h1><p>{course.description}</p></div><div className="lesson-list">{lessons.map((l,i)=><button className="lesson-row" key={l.id} onClick={()=>openLesson(l)}><span className="lesson-number">{String(i+1).padStart(2,'0')}</span><span><strong>{l.title}</strong><small>{l.summary||'Aula prática'} · {l.estimated_minutes||10} min</small></span><ChevronRight/></button>)}</div></section>}

function inlineLessonText(value){
  return String(value).split(/(\*\*[^*]+\*\*)/g).map((part,index)=>part.startsWith('**')?<strong key={index}>{part.slice(2,-2)}</strong>:part)
}
function MarkdownContent({content}){
  const chunks=String(content||'O conteúdo desta aula está sendo preparado. Use o tutor para tirar dúvidas sobre este tema.').replace(/\r/g,'').split(String.fromCharCode(96).repeat(3))
  return <div className="markdown-content">{chunks.map((chunk,chunkIndex)=>{
    if(chunkIndex%2===1){
      const codeLines=chunk.split('\n')
      const language=/^[a-zA-Z0-9_+#.-]+$/.test((codeLines[0]||'').trim())?codeLines.shift().trim():''
      return <pre className="lesson-code" data-language={language} key={chunkIndex}><code>{codeLines.join('\n').replace(/^\n|\n$/g,'')}</code></pre>
    }
    const lines=chunk.split('\n'),elements=[]
    for(let i=0;i<lines.length;){
      const line=lines[i].trim()
      if(!line){i++;continue}
      if(/^#{1,3}\s/.test(line)){
        const depth=(line.match(/^#+/)||['##'])[0].length
        const Heading=depth===1?'h2':depth===2?'h2':'h3'
        elements.push(<Heading key={i}>{inlineLessonText(line.replace(/^#+\s*/,''))}</Heading>);i++;continue
      }
      if(/^[-*]\s+/.test(line)){
        const items=[]
        while(i<lines.length&&/^\s*[-*]\s+/.test(lines[i])){items.push(lines[i].replace(/^\s*[-*]\s+/,''));i++}
        elements.push(<ul key={i}>{items.map((item,k)=><li key={k}>{inlineLessonText(item)}</li>)}</ul>);continue
      }
      if(/^\d+[.)]\s+/.test(line)){
        const items=[]
        while(i<lines.length&&/^\s*\d+[.)]\s+/.test(lines[i])){items.push(lines[i].replace(/^\s*\d+[.)]\s+/,''));i++}
        elements.push(<ol key={i}>{items.map((item,k)=><li key={k}>{inlineLessonText(item)}</li>)}</ol>);continue
      }
      if(line.startsWith('> ')){elements.push(<blockquote key={i}>{inlineLessonText(line.slice(2))}</blockquote>);i++;continue}
      const paragraph=[lines[i].trim()];i++
      while(i<lines.length&&lines[i].trim()&&!/^#{1,3}\s|^[-*]\s+|^\d+[.)]\s+|^> /.test(lines[i].trim())){paragraph.push(lines[i].trim());i++}
      elements.push(<p key={i}>{inlineLessonText(paragraph.join(' '))}</p>)
    }
    return <div key={chunkIndex}>{elements}</div>
  })}</div>
}

function Lesson({lesson,course,back,complete,ask,saveProject}){
  const [tab,setTab]=useState('learn'),[projectTitle,setProjectTitle]=useState(''),[projectDescription,setProjectDescription]=useState(''),[projectUrl,setProjectUrl]=useState(''),[saving,setSaving]=useState(false),[message,setMessage]=useState('')
  async function submit(e){e.preventDefault();setSaving(true);const ok=await saveProject(lesson,{title:projectTitle||('Entrega prática: '+lesson.title),description:projectDescription,url:projectUrl});setSaving(false);if(ok){setProjectTitle('');setProjectDescription('');setProjectUrl('');setMessage('Enviado. Seu administrador poderá revisar e deixar feedback.')}} 
  const challenge='Aplique o conteúdo “'+lesson.title+'” em uma entrega pequena e verificável. Explique o que você fez, por que escolheu esse caminho e qual resultado observou.';
  return <section className="workspace lesson-page"><button className="back-button" onClick={back}>← {course?.title||'Voltar'}</button><span className="eyebrow">AULA · {lesson.estimated_minutes||10} MIN</span><h1>{lesson.title}</h1><p className="lesson-summary">{lesson.summary}</p>
    <div className="lesson-tabs"><button className={tab==='learn'?'active':''} onClick={()=>setTab('learn')}><BookOpen size={15}/> Entender</button><button className={tab==='practice'?'active':''} onClick={()=>setTab('practice')}><Target size={15}/> Colocar em prática</button><button className={tab==='review'?'active':''} onClick={()=>setTab('review')}><CheckCircle2 size={15}/> Revisar e enviar</button></div>
    {tab==='learn'&&<><article className="lesson-content"><MarkdownContent content={lesson.content_md}/></article><div className="lesson-actions"><button className="button" onClick={()=>setTab('practice')}>Ir para a missão <ArrowRight size={15}/></button><button className="outline-button" onClick={ask}><MessageCircle/> Estudar com o tutor IA</button></div></>}
    {tab==='practice'&&<div className="panel lesson-mission"><span className="eyebrow">MISSÃO DE APLICAÇÃO</span><h2>Transforme a aula em uma entrega.</h2><p>{challenge}</p><div className="mission-checklist"><div><CheckCircle2/><span>Identifique o problema ou objetivo que está tentando resolver.</span></div><div><CheckCircle2/><span>Mostre o processo: etapas, ferramenta e decisões que tomou.</span></div><div><CheckCircle2/><span>Registre o resultado e uma melhoria que faria na próxima versão.</span></div></div><div className="concept-note"><strong>Critério de conclusão</strong><p>Uma pessoa que não viu sua execução deve conseguir entender o que você fez, reproduzir as etapas e avaliar o resultado. Não precisa ser perfeito: precisa ser verificável.</p></div><div className="lesson-actions"><button className="button" onClick={()=>setTab('review')}>Preparar minha entrega <ArrowRight size={15}/></button><button className="outline-button" onClick={ask}>Pedir orientação à IA</button></div></div>}
    {tab==='review'&&<div className="panel lesson-mission"><span className="eyebrow">PORTFÓLIO E FEEDBACK</span><h2>Envie o que você produziu.</h2><p>O trabalho fica associado à sua conta e aparece no ADMIN para revisão. Inclua um link público apenas se não expuser dados privados.</p><form className="admin-form" onSubmit={submit}><label>Título da entrega<input value={projectTitle} onChange={e=>setProjectTitle(e.target.value)} placeholder={'Ex.: Minha aplicação de '+lesson.title}/></label><label>O que você fez? Quais etapas seguiu e qual foi o resultado?<textarea rows="7" required minLength="15" maxLength="10000" value={projectDescription} onChange={e=>setProjectDescription(e.target.value)} placeholder="Explique sua execução, mostre decisões, resultado e o que aprendeu…"/></label><label>Link da entrega (opcional)<input type="url" value={projectUrl} onChange={e=>setProjectUrl(e.target.value)} placeholder="https://…"/></label><button className="button" disabled={saving}>{saving?'Enviando…':'Enviar para revisão'} <Send size={15}/></button></form>{message&&<p className="notice">{message}</p>}<p className="admin-footnote">Não envie senhas, chaves privadas, documentos pessoais ou dados de clientes. Para uma entrega privada, descreva o processo sem publicar informações sensíveis.</p></div>}
    <div className="lesson-completion-bar"><span>Terminou de estudar?</span><button className="outline-button" onClick={complete}>Marcar aula como concluída <CheckCircle2 size={15}/></button></div>
  </section>
}

function Tools({tools,profile,onOpen}){
  const list=tools.filter(t=>t.is_published&&(profile?.age_group==='adult'||!t.adult_only))
  return <section className="workspace tools-page">
    <div className="section-heading left"><span className="eyebrow">BIBLIOTECA AZELF</span><h1>Ferramentas para executar, não apenas conhecer.</h1><p>Links oficiais organizados por finalidade. Abra, compare os limites e escolha a ferramenta conforme a tarefa. A AZELF não controla preços, políticas ou disponibilidade de terceiros.</p></div>
    <div className="panel-title"><div><span className="eyebrow">CATÁLOGO DE IA E TECNOLOGIA</span><h2>Biblioteca de ferramentas</h2></div><span className="status-pill active">{list.length} links ativos</span></div>
    <div className="ai-tool-grid">{list.map(t=><article className="ai-tool-card" key={t.id}><span className="tool-icon"><BrainCircuit/></span><div className="ai-tool-meta">{t.category}</div><h3>{t.name}</h3><p>{t.description}</p><small>{t.access_label}</small>{t.tutorial&&<details><summary>Como começar</summary><p>{t.tutorial}</p></details>}<a href={t.official_url} target="_blank" rel="noopener noreferrer" onClick={()=>onOpen?.(t.name)}>Abrir site oficial <ExternalLink size={14}/></a></article>)}</div>
    {list.length===0&&<div className="panel affiliate-empty"><BrainCircuit/><h2>Biblioteca ainda não publicada</h2><p>Entre com uma conta com acesso para consultar as ferramentas liberadas.</p></div>}
    <p className="admin-footnote">Não compartilhe senhas, documentos confidenciais, dados financeiros ou informações pessoais com serviços externos sem avaliar suas políticas.</p>
  </section>
}
function Onboarding({answers,setAnswers,fullName,setFullName,save,saving,notice}){function set(k,v){setAnswers(a=>({...a,[k]:v}))}function area(name){set('areas',answers.areas.includes(name)?answers.areas.filter(x=>x!==name):[...answers.areas,name])}return <section className="onboarding"><div className="onboarding-head"><span className="eyebrow">DIAGNÓSTICO INICIAL</span><h1>Vamos descobrir seu próximo passo.</h1><p>Suas respostas ajudam a organizar uma jornada de aprendizagem mais relevante.</p></div><form onSubmit={save} className="onboarding-form"><label>Como podemos chamar você?<input value={fullName} onChange={e=>setFullName(e.target.value)} placeholder="Seu nome"/></label><fieldset><legend>1. Qual é seu principal objetivo agora?</legend><div className="choice-grid">{goals.map(g=><button type="button" className={answers.goal===g?'choice selected':'choice'} onClick={()=>set('goal',g)} key={g}>{g}</button>)}</div></fieldset><fieldset><legend>2. Quais áreas você quer explorar?</legend><div className="choice-grid">{areas.map(a=><button type="button" className={answers.areas.includes(a.name)?'choice selected':'choice'} onClick={()=>area(a.name)} key={a.name}>{a.name}</button>)}</div></fieldset><fieldset><legend>3. Quanto tempo você pode dedicar por dia?</legend><div className="choice-grid">{timeOptions.map(t=><button type="button" className={answers.time===t?'choice selected':'choice'} onClick={()=>set('time',t)} key={t}>{t}</button>)}</div></fieldset><fieldset><legend>4. Como você descreve seu momento atual?</legend><div className="choice-grid">{['Estou começando do zero','Já estudo por conta própria','Já trabalho ou vendo algo','Tenho um negócio ou projeto'].map(t=><button type="button" className={answers.experience===t?'choice selected':'choice'} onClick={()=>set('experience',t)} key={t}>{t}</button>)}</div></fieldset><fieldset><legend>5. Quais plataformas ou ferramentas você já conhece?</legend><label><input value={answers.known_platforms} onChange={e=>set('known_platforms',e.target.value)} placeholder="Ex.: Canva, Instagram, Excel, ChatGPT, Shopify…"/></label><small>Liste apenas nomes de plataformas; não informe senhas ou dados privados.</small></fieldset><fieldset><legend>6. Com o que você trabalha, estuda ou costuma fazer?</legend><label><input value={answers.current_activity} onChange={e=>set('current_activity',e.target.value)} placeholder="Ex.: estudante, comércio, edição de vídeo, atendimento…"/></label></fieldset><fieldset><legend>7. O que gostaria de conquistar nos próximos seis meses?</legend><label><input value={answers.six_month_goal} onChange={e=>set('six_month_goal',e.target.value)} placeholder="Descreva uma meta concreta."/></label></fieldset><fieldset><legend>8. Qual é sua visão de futuro ou maior objetivo?</legend><label><input value={answers.personal_vision} onChange={e=>set('personal_vision',e.target.value)} placeholder="O que você gostaria de construir a longo prazo?"/></label></fieldset><fieldset><legend>9. Qual é sua faixa etária?</legend><div className="choice-grid"><button type="button" className={answers.age_group==='minor'?'choice selected':'choice'} onClick={()=>set('age_group','minor')}>Menos de 18 anos</button><button type="button" className={answers.age_group==='adult'?'choice selected':'choice'} onClick={()=>set('age_group','adult')}>18 anos ou mais</button></div><small>Essa informação serve para adequar conteúdos e proteger sua experiência. Recursos restritos permanecem sujeitos a verificações adicionais.</small>{answers.age_group==='minor'&&<label>E-mail do responsável legal<input type="email" value={answers.guardian_email} onChange={e=>set('guardian_email',e.target.value)} required placeholder="responsavel@email.com"/></label>}</fieldset><fieldset><legend>10. Qual faixa representa sua idade?</legend><div className="choice-grid">{['13–15 anos','16–17 anos','18–24 anos','25–34 anos','35–44 anos','45 anos ou mais'].map(v=><button type="button" className={answers.age_bracket===v?'choice selected':'choice'} onClick={()=>set('age_bracket',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>11. Quais habilidades você já sabe fazer?</legend><label><textarea rows="3" value={answers.skills_available||''} onChange={e=>set('skills_available',e.target.value)} placeholder="Ex.: edição, atendimento, escrita, design, vendas, organização…"/></label></fieldset><fieldset><legend>12. Você já tem público ou clientes?</legend><div className="choice-grid">{['Ainda não','Amigos e contatos próximos','Até 500 seguidores/clientes','Mais de 500','Já tenho clientes recorrentes'].map(v=><button type="button" className={answers.audience===v?'choice selected':'choice'} onClick={()=>set('audience',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>13. Como você aprende melhor?</legend><div className="choice-grid">{['Vídeos curtos e demonstrações','Passo a passo com prática','Projetos e desafios','Leitura com exemplos','Mistura de tudo'].map(v=><button type="button" className={answers.learning_style===v?'choice selected':'choice'} onClick={()=>set('learning_style',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>14. O que mais está dificultando seu avanço?</legend><div className="choice-grid">{['Não sei por onde começar','Falta de tempo','Falta de dinheiro para ferramentas','Falta de confiança ou orientação','Não consigo encontrar clientes','Já comecei, mas não termino'].map(v=><button type="button" className={answers.biggest_blocker===v?'choice selected':'choice'} onClick={()=>set('biggest_blocker',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>15. O que você gostaria de ensinar a outra pessoa?</legend><label><textarea rows="3" value={answers.teachable_skills||''} onChange={e=>set('teachable_skills',e.target.value)} placeholder="Mesmo que pareça simples, conte o que você sabe fazer."/></label></fieldset><button className="button" disabled={saving||!answers.goal||!answers.areas.length||!answers.time||!answers.experience||!answers.age_group||(answers.age_group==='minor'&&!answers.guardian_email.trim())}>{saving?'Salvando…':'Salvar diagnóstico e montar minha jornada'} <ArrowRight/></button>{notice&&<p className="notice">{notice}</p>}</form></section>}
function Admin({courses,lessons,tools,profile,refresh}){
  const [tab,setTab]=useState('overview'),[stats,setStats]=useState({users:0,active:0,pending:0,lessonsDone:0,questions:0,openTickets:0,activity7d:0}),[trend,setTrend]=useState([])
  const [users,setUsers]=useState([]),[codes,setCodes]=useState([]),[events,setEvents]=useState([]),[tickets,setTickets]=useState([]),[posts,setPosts]=useState([]),[projects,setProjects]=useState([])
  const [selectedProject,setSelectedProject]=useState(null),[projectFeedback,setProjectFeedback]=useState(''),[projectStatus,setProjectStatus]=useState('reviewed')
  const [affiliateRows,setAffiliateRows]=useState([]),[partnerLinks,setPartnerLinks]=useState([]),[affiliateId,setAffiliateId]=useState(null),[affiliatePlatform,setAffiliatePlatform]=useState('mercado_livre'),[affiliateTitle,setAffiliateTitle]=useState(''),[affiliateDescription,setAffiliateDescription]=useState(''),[affiliateCategory,setAffiliateCategory]=useState('geral'),[affiliateProductUrl,setAffiliateProductUrl]=useState(''),[affiliateUrl,setAffiliateUrl]=useState(''),[affiliateImageUrl,setAffiliateImageUrl]=useState(''),[affiliatePrice,setAffiliatePrice]=useState(''),[affiliateDisclosure,setAffiliateDisclosure]=useState('Este conteúdo contém link de afiliado. A AZELF pode receber comissão se você comprar por ele, conforme as regras do parceiro.'),[affiliatePublished,setAffiliatePublished]=useState(false)
  const [email,setEmail]=useState(''),[label,setLabel]=useState(''),[days,setDays]=useState(30),[newCode,setNewCode]=useState('')
  const [selectedTicket,setSelectedTicket]=useState(null),[reply,setReply]=useState(''),[ticketStatus,setTicketStatus]=useState('in_progress')
  const [platform,setPlatform]=useState('instagram'),[postTitle,setPostTitle]=useState(''),[caption,setCaption]=useState(''),[mediaUrl,setMediaUrl]=useState(''),[postDate,setPostDate]=useState(''),[postStatus,setPostStatus]=useState('draft'),[publishedUrl,setPublishedUrl]=useState(''),[postId,setPostId]=useState(null),[postViews,setPostViews]=useState(0),[postLikes,setPostLikes]=useState(0),[postComments,setPostComments]=useState(0),[postClicks,setPostClicks]=useState(0),[postLeads,setPostLeads]=useState(0)
  const [courseId,setCourseId]=useState(courses[0]?.id||''),[courseTitle,setCourseTitle]=useState(''),[courseDescription,setCourseDescription]=useState(''),[courseCategory,setCourseCategory]=useState('Negócios'),[editingCourse,setEditingCourse]=useState(null)
  const [toolId,setToolId]=useState(null),[toolName,setToolName]=useState(''),[toolCategory,setToolCategory]=useState('Inteligência artificial'),[toolDescription,setToolDescription]=useState(''),[toolAccess,setToolAccess]=useState('Consulte os planos e limites no site oficial.'),[toolUrl,setToolUrl]=useState(''),[toolTutorial,setToolTutorial]=useState(''),[toolAdultOnly,setToolAdultOnly]=useState(false),[toolPublished,setToolPublished]=useState(false)
  const [lessonTitle,setLessonTitle]=useState(''),[lessonSummary,setLessonSummary]=useState(''),[lessonContent,setLessonContent]=useState(''),[lessonMinutes,setLessonMinutes]=useState(25),[editingLesson,setEditingLesson]=useState(null)
  const [labTitle,setLabTitle]=useState(''),[labDescription,setLabDescription]=useState('')
  const [busy,setBusy]=useState(false),[message,setMessage]=useState(''),[filter,setFilter]=useState('')
  async function call(name,body){const {data,error}=await supabase.functions.invoke(name,{body});if(error)throw error;if(data?.error)throw new Error(data.error);return data}
  async function loadOverview(){try{const d=await call('admin-manage',{action:'overview'});setStats(s=>({...s,...d.stats}))}catch(e){setMessage(e.message)}}
  async function loadDashboard(){try{const d=await call('admin-manage',{action:'admin-dashboard'});setStats(s=>({...s,...d.stats}));setTrend(d.trend||[])}catch(e){setMessage(e.message)}}
  async function loadUsers(){try{const d=await call('admin-manage',{action:'users'});setUsers(d.users||[])}catch(e){setMessage(e.message)}}
  async function loadCodes(){try{const d=await call('admin-codes',{action:'list'});setCodes(d.codes||[])}catch(e){setMessage(e.message)}}
  async function loadEvents(){try{const d=await call('admin-manage',{action:'activity'});setEvents(d.events||[])}catch(e){setMessage(e.message)}}
  async function loadTickets(){try{const d=await call('admin-manage',{action:'tickets'});setTickets(d.tickets||[])}catch(e){setMessage(e.message)}}
  async function loadPosts(){try{const d=await call('admin-manage',{action:'social-posts'});setPosts(d.posts||[])}catch(e){setMessage(e.message)}}
  async function loadProjects(){try{const d=await call('admin-manage',{action:'student-projects'});setProjects(d.projects||[])}catch(e){setMessage(e.message)}}
  async function loadAffiliateRows(){const {data,error}=await supabase.from('affiliate_products').select('*').order('sort_order');if(error)setMessage(error.message);else setAffiliateRows(data||[])}
  async function loadPartnerLinks(){const {data,error}=await supabase.from('student_affiliate_links').select('*').order('updated_at',{ascending:false}).limit(300);if(error)setMessage(error.message);else setPartnerLinks(data||[])}
  async function deletePartnerLink(id){if(!confirm('Remover este link cadastrado pelo aluno?'))return;const {error}=await supabase.from('student_affiliate_links').delete().eq('id',id);if(error)setMessage(error.message);else{setMessage('Link do aluno removido.');await loadPartnerLinks()}}
  useEffect(()=>{loadOverview();loadDashboard()},[])
  useEffect(()=>{if(courses.length&&!courses.some(c=>c.id===courseId))setCourseId(courses[0].id)},[courses,courseId])
  useEffect(()=>{
    const channel=supabase.channel('azelf-admin-live')
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'support_tickets'},payload=>{
        setMessage('Nova solicitação de suporte recebida.');
        if(tab==='tickets')loadTickets();
        loadDashboard();
      })
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'student_projects'},payload=>{
        setMessage('Novo projeto de aluno enviado para revisão.');
        if(tab==='projects')loadProjects();
        loadDashboard();
      })
      .on('postgres_changes',{event:'INSERT',schema:'public',table:'learning_activity'},payload=>{
        if(payload.new?.event_type==='tutor_question')setMessage('Novo aluno fez uma pergunta ao tutor IA.');
        if(tab==='activity')loadEvents();
        if(['tutor_question','lesson_completed'].includes(payload.new?.event_type))loadDashboard();
      })
      .subscribe();
    return ()=>{supabase.removeChannel(channel)}
  },[tab])

  async function switchTab(next){setTab(next);setMessage('');if(next==='users')await loadUsers();if(next==='codes')await loadCodes();if(next==='activity')await loadEvents();if(next==='tickets')await loadTickets();if(next==='social')await loadPosts();if(next==='projects')await loadProjects();if(next==='affiliates')await loadAffiliateRows();if(next==='partners')await loadPartnerLinks();if(next==='overview'){await loadOverview();await loadDashboard()}}
  async function generate(e){e.preventDefault();setBusy(true);setMessage('');setNewCode('');try{const d=await call('admin-codes',{action:'generate',customer_email:email,customer_label:label,validity_days:Number(days)});setNewCode(d.code||'');setMessage(d.warning||'Código gerado. Copie agora; ele não será exibido novamente.');setEmail('');setLabel('');await loadCodes();await loadOverview()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function revoke(id){if(!confirm('Revogar este código não utilizado?'))return;try{await call('admin-codes',{action:'revoke',id});setMessage('Código revogado.');await loadCodes();await loadOverview()}catch(e){setMessage(e.message)}}
  async function setUserStatus(user,status){const minorApproval=status==='active'&&user.age_group==='minor'&&user.guardian_consent_status!=='approved';const prompt=minorApproval?'Confirme que o consentimento do responsável legal foi realmente recebido e verificado.':' '+(status==='active'?'Ativar':'Suspender')+' o acesso de '+(user.email||user.full_name)+'?';if(!confirm(prompt))return;try{if(minorApproval)await call('admin-manage',{action:'approve-guardian',user_id:user.id});else await call('admin-manage',{action:'set-user-status',user_id:user.id,status});setMessage(minorApproval?'Verificação manual do responsável registrada.':'Acesso atualizado.');await loadUsers();await loadOverview()}catch(e){setMessage(e.message)}}
  async function answerTicket(e){e.preventDefault();if(!selectedTicket)return;setBusy(true);try{await call('admin-manage',{action:'ticket-reply',id:selectedTicket.id,admin_reply:reply,status:ticketStatus});setMessage('Resposta e status salvos.');setReply('');setSelectedTicket(null);await loadTickets();await loadDashboard()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function reviewProject(e){e.preventDefault();if(!selectedProject)return;setBusy(true);try{await call('admin-manage',{action:'project-feedback',id:selectedProject.id,mentor_feedback:projectFeedback,status:projectStatus});setMessage('Feedback salvo no projeto do aluno.');setSelectedProject(null);setProjectFeedback('');await loadProjects()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function saveAffiliate(e){e.preventDefault();setBusy(true);try{const values={platform:affiliatePlatform,title:affiliateTitle,description:affiliateDescription,category:affiliateCategory,product_url:affiliateProductUrl,affiliate_url:affiliateUrl||null,image_url:affiliateImageUrl||null,price_label:affiliatePrice||null,disclosure:affiliateDisclosure,adult_only:false,is_published:affiliatePublished,updated_at:new Date().toISOString()};const result=affiliateId?await supabase.from('affiliate_products').update(values).eq('id',affiliateId):await supabase.from('affiliate_products').insert({...values,created_by:profile?.id||null});if(result.error)throw result.error;setMessage('Recomendação salva. Se publicada, aparecerá na página Recomendações.');setAffiliateId(null);setAffiliateTitle('');setAffiliateDescription('');setAffiliateProductUrl('');setAffiliateUrl('');setAffiliateImageUrl('');setAffiliatePrice('');setAffiliatePublished(false);await loadAffiliateRows()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  function editAffiliate(p){setAffiliateId(p.id);setAffiliatePlatform(p.platform);setAffiliateTitle(p.title);setAffiliateDescription(p.description||'');setAffiliateCategory(p.category||'geral');setAffiliateProductUrl(p.product_url||'');setAffiliateUrl(p.affiliate_url||'');setAffiliateImageUrl(p.image_url||'');setAffiliatePrice(p.price_label||'');setAffiliateDisclosure(p.disclosure||'');setAffiliatePublished(p.is_published)}
  async function deleteAffiliate(id){if(!confirm('Excluir esta recomendação?'))return;const {error}=await supabase.from('affiliate_products').delete().eq('id',id);if(error)setMessage(error.message);else{setMessage('Recomendação removida.');await loadAffiliateRows()}}
  async function savePost(e){e.preventDefault();setBusy(true);try{await call('admin-manage',{action:'social-save',id:postId,platform,title:postTitle,caption,media_url:mediaUrl,scheduled_at:postDate?new Date(postDate).toISOString():null,status:postStatus,published_url:publishedUrl,performance:{views:postViews,likes:postLikes,comments:postComments,clicks:postClicks,leads:postLeads}});setMessage(postId?'Publicação e métricas atualizadas.':'Publicação adicionada ao calendário. A postagem automática depende da integração oficial da rede.');setPostId(null);setPostTitle('');setCaption('');setMediaUrl('');setPostDate('');setPublishedUrl('');setPostStatus('draft');setPostViews(0);setPostLikes(0);setPostComments(0);setPostClicks(0);setPostLeads(0);await loadPosts()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  function editPost(post){setPostId(post.id);setPlatform(post.platform);setPostTitle(post.title);setCaption(post.caption||'');setMediaUrl(post.media_url||'');setPostDate(post.scheduled_at?new Date(post.scheduled_at).toISOString().slice(0,16):'');setPostStatus(post.status);setPublishedUrl(post.published_url||'');setPostViews(post.performance?.views||0);setPostLikes(post.performance?.likes||0);setPostComments(post.performance?.comments||0);setPostClicks(post.performance?.clicks||0);setPostLeads(post.performance?.leads||0)}
  async function deletePost(id){if(!confirm('Excluir este item do calendário?'))return;try{await call('admin-manage',{action:'social-delete',id});await loadPosts();setMessage('Item removido.')}catch(e){setMessage(e.message)}}
  async function createCourse(e){e.preventDefault();setBusy(true);try{const slug=courseTitle.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+Date.now().toString(36);const {error}=await supabase.from('courses').insert({title:courseTitle,slug,description:courseDescription,category:courseCategory,icon:'book-open',is_published:false,adult_only:false,sort_order:courses.length+1});if(error)throw error;setMessage('Trilha criada como rascunho. Ela já ficará disponível no editor para receber aulas.');setCourseTitle('');setCourseDescription('');await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function createLesson(e){e.preventDefault();if(!courseId){setMessage('Selecione a trilha.');return}setBusy(true);try{const {error}=await supabase.from('lessons').insert({course_id:courseId,title:lessonTitle,summary:lessonSummary,content_md:lessonContent,estimated_minutes:Number(lessonMinutes),is_published:false,adult_only:false,sort_order:lessons.filter(l=>l.course_id===courseId).length+1});if(error)throw error;setMessage('Aula criada como rascunho. Publique a aula e a trilha quando estiverem prontas.');setLessonTitle('');setLessonSummary('');setLessonContent('');await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function updateLesson(e){e.preventDefault();if(!editingLesson)return;setBusy(true);try{const {error}=await supabase.from('lessons').update({title:lessonTitle,summary:lessonSummary,content_md:lessonContent,estimated_minutes:Number(lessonMinutes),updated_at:new Date().toISOString()}).eq('id',editingLesson);if(error)throw error;setMessage('Aula atualizada.');setEditingLesson(null);setLessonTitle('');setLessonSummary('');setLessonContent('');await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function updateCourse(e){e.preventDefault();if(!editingCourse)return;setBusy(true);try{const {error}=await supabase.from('courses').update({title:courseTitle,description:courseDescription,category:courseCategory,updated_at:new Date().toISOString()}).eq('id',editingCourse);if(error)throw error;setMessage('Trilha atualizada.');setEditingCourse(null);setCourseTitle('');setCourseDescription('');await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  function editCourse(course){setEditingCourse(course.id);setCourseId(course.id);setCourseTitle(course.title);setCourseDescription(course.description||'');setCourseCategory(course.category||'Geral')}
  async function deleteCourse(course){if(!confirm('Excluir a trilha “'+course.title+'”? As aulas e o progresso associado serão removidos. As entregas de projetos permanecem no portfólio, desvinculadas desta trilha.'))return;setBusy(true);try{const {error}=await supabase.from('courses').delete().eq('id',course.id);if(error)throw error;setMessage('Trilha excluída. As entregas existentes foram preservadas.');if(editingCourse===course.id){setEditingCourse(null);setCourseTitle('');setCourseDescription('')}await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function deleteLesson(lesson){if(!confirm('Excluir a aula “'+lesson.title+'”? O progresso associado será removido, mas entregas já enviadas serão preservadas no portfólio.'))return;setBusy(true);try{const {error}=await supabase.from('lessons').delete().eq('id',lesson.id);if(error)throw error;setMessage('Aula excluída. Entregas existentes preservadas.');if(editingLesson===lesson.id){setEditingLesson(null);setLessonTitle('');setLessonSummary('');setLessonContent('')}await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function saveTool(e){e.preventDefault();setBusy(true);try{const slug=toolName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');const values={name:toolName.trim(),slug,category:toolCategory.trim(),description:toolDescription.trim(),access_label:toolAccess.trim(),official_url:toolUrl.trim(),tutorial:toolTutorial.trim()||null,adult_only:toolAdultOnly,is_published:toolPublished,updated_at:new Date().toISOString()};const result=toolId?await supabase.from('tools').update(values).eq('id',toolId):await supabase.from('tools').insert({...values,sort_order:tools.length+1});if(result.error)throw result.error;setMessage(toolId?'Ferramenta atualizada.':'Ferramenta cadastrada.');resetToolForm();await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  function resetToolForm(){setToolId(null);setToolName('');setToolCategory('Inteligência artificial');setToolDescription('');setToolAccess('Consulte os planos e limites no site oficial.');setToolUrl('');setToolTutorial('');setToolAdultOnly(false);setToolPublished(false)}
  function editTool(tool){setToolId(tool.id);setToolName(tool.name);setToolCategory(tool.category);setToolDescription(tool.description);setToolAccess(tool.access_label||'');setToolUrl(tool.official_url);setToolTutorial(tool.tutorial||'');setToolAdultOnly(tool.adult_only);setToolPublished(tool.is_published)}
  async function toggleToolPublished(tool){setBusy(true);try{const {error}=await supabase.from('tools').update({is_published:!tool.is_published,updated_at:new Date().toISOString()}).eq('id',tool.id);if(error)throw error;setMessage(tool.is_published?'Ferramenta despublicada.':'Ferramenta publicada.');await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function deleteTool(id){if(!confirm('Excluir este link da biblioteca?'))return;const {error}=await supabase.from('tools').delete().eq('id',id);if(error)setMessage(error.message);else{setMessage('Ferramenta excluída.');await refresh?.()}}
  function editLesson(lesson){setEditingLesson(lesson.id);setCourseId(lesson.course_id);setLessonTitle(lesson.title);setLessonSummary(lesson.summary||'');setLessonContent(lesson.content_md||'');setLessonMinutes(lesson.estimated_minutes||25)}
  async function createLab(e){e.preventDefault();setBusy(true);try{const slug='lab-'+labTitle.toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+Date.now().toString(36);const {data,error}=await supabase.from('courses').insert({title:labTitle,slug,description:labDescription,category:'Laboratórios',icon:'blocks',is_published:false,adult_only:false,sort_order:courses.length+1}).select('id').single();if(error)throw error;await refresh?.();setCourseId(data.id);setLabTitle('');setLabDescription('');setMessage('Laboratório criado como rascunho. Agora adicione as etapas e publique quando estiver pronto.');setTab('content')}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function toggleCoursePublished(course){setBusy(true);try{const {error}=await supabase.from('courses').update({is_published:!course.is_published,updated_at:new Date().toISOString()}).eq('id',course.id);if(error)throw error;setMessage(course.is_published?'Trilha despublicada.':'Trilha publicada.');await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function toggleLessonPublished(lesson){setBusy(true);try{const {error}=await supabase.from('lessons').update({is_published:!lesson.is_published,updated_at:new Date().toISOString()}).eq('id',lesson.id);if(error)throw error;setMessage(lesson.is_published?'Aula despublicada.':'Aula publicada.');await refresh?.()}catch(e){setMessage(e.message)}finally{setBusy(false)}}

  const fmt=d=>d?new Date(d).toLocaleString('pt-BR'):'—'
  const filteredUsers=users.filter(u=>!filter||[u.full_name,u.email,u.age_group,u.access_status].join(' ').toLowerCase().includes(filter.toLowerCase()))
  const activityLabel={login:'Entrou na plataforma',onboarding_completed:'Concluiu diagnóstico',course_opened:'Abriu uma trilha',lesson_opened:'Abriu uma aula',lesson_completed:'Concluiu uma aula',tutor_question:'Perguntou ao tutor IA',tool_opened:'Abriu uma ferramenta',support_requested:'Solicitou suporte',project_created:'Criou um projeto'}
  return <section className="workspace admin-workspace">
    <div className="section-heading left"><span className="eyebrow"><ShieldCheck size={14}/> CONTROLE ADMINISTRATIVO</span><h1>Painel de comando AZELF</h1><p>Usuários, aprendizagem, dúvidas, suporte, conteúdo e calendário editorial.</p></div>
    <div className="stats-grid admin-kpis"><Stat label="Usuários cadastrados" value={stats.users} icon={Users}/><Stat label="Acessos ativos" value={stats.active} icon={CheckCircle2}/><Stat label="Aguardando análise" value={stats.pending} icon={ShieldAlert}/><Stat label="Aulas concluídas" value={stats.lessonsDone} icon={GraduationCap}/><Stat label="Perguntas à IA (7 dias)" value={stats.questions} icon={MessageCircle}/><Stat label="Tickets em aberto" value={stats.openTickets} icon={Ticket}/></div>
    <div className="admin-tabs">{[['overview','Visão geral'],['users','Alunos'],['activity','Atividade e dúvidas'],['tickets','Suporte'],['projects','Projetos'],['codes','Convites'],['labs','Laboratórios'],['content','Cursos e aulas'],['tools','Ferramentas e IAs'],['affiliates','Afiliados'],['partners','Links dos alunos'],['social','Redes sociais']].map(([k,v])=><button key={k} className={tab===k?'active':''} onClick={()=>switchTab(k)}>{v}</button>)}</div>
    {tab==='overview'&&<div className="admin-overview-grid"><div className="panel admin-chart-panel"><div className="panel-title"><div><span className="eyebrow">ENGAJAMENTO</span><h2>Atividade nos últimos 7 dias</h2></div><button className="outline-button" onClick={loadDashboard}>Atualizar</button></div><ActivityTrend data={trend}/><div className="chart-legend"><span><i className="legend-dot activity-dot"/> Atividade</span><span><i className="legend-dot lesson-dot"/> Aulas concluídas</span><span><i className="legend-dot question-dot"/> Dúvidas à IA</span></div></div><div className="panel admin-shortcuts"><span className="eyebrow">OPERAÇÃO</span><h2>O que precisa de atenção?</h2><button className="admin-shortcut" onClick={()=>switchTab('tickets')}><Ticket/> <span><strong>{stats.openTickets} solicitações</strong><small>Responder alunos que pediram ajuda</small></span><ChevronRight/></button><button className="admin-shortcut" onClick={()=>switchTab('activity')}><MessageCircle/><span><strong>{stats.questions} perguntas recentes</strong><small>Entender dúvidas e pontos de abandono</small></span><ChevronRight/></button><button className="admin-shortcut" onClick={()=>switchTab('social')}><CalendarDays/><span><strong>Calendário editorial</strong><small>Organizar vídeos, posts e links publicados</small></span><ChevronRight/></button><button className="admin-shortcut" onClick={()=>switchTab('content')}><BookOpen/><span><strong>Gestão de conteúdo</strong><small>Criar trilhas e aulas práticas</small></span><ChevronRight/></button></div></div>}
    {tab==='users'&&<div className="panel"><div className="panel-title"><div><span className="eyebrow">BASE DE ALUNOS</span><h2>Quem está usando a AZELF</h2></div><button className="outline-button" onClick={loadUsers}>Atualizar</button></div><div className="search-box"><Search/><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Buscar por nome, e-mail ou status…"/></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Aluno</th><th>Perfil</th><th>Acesso</th><th>Cadastro</th><th>Ação</th></tr></thead><tbody>{filteredUsers.map(u=><tr key={u.id}><td><strong>{u.full_name||'Nome não informado'}</strong><small>{u.email}</small></td><td>{u.role==='admin'?'ADMIN':u.age_group==='minor'?'Menor':'Adulto'}</td><td><span className={'status-pill '+u.access_status}>{u.access_status}</span>{u.guardian_consent_status==='pending'&&<small>Responsável pendente</small>}</td><td>{new Date(u.created_at).toLocaleDateString('pt-BR')}</td><td>{u.role!=='admin'&&(u.access_status==='active'?<button className="danger-button" onClick={()=>setUserStatus(u,'suspended')}>Suspender</button>:<button className="mini-button" onClick={()=>setUserStatus(u,'active')}>{u.age_group==='minor'&&u.guardian_consent_status!=='approved'?'Validar responsável':'Ativar'}</button>)}<button className="text-button" onClick={()=>{setFilter(u.email);switchTab('activity');loadEvents()}}>Ver atividade</button></td></tr>)}</tbody></table></div><p className="admin-footnote">E-mail e status vêm do Supabase Auth e das tabelas protegidas. A lista é limitada aos 200 cadastros mais recentes nesta versão.</p></div>}
    {tab==='activity'&&<div className="panel"><div className="panel-title"><div><span className="eyebrow">RASTREAMENTO DE APRENDIZAGEM</span><h2>O que os alunos estão fazendo</h2></div><button className="outline-button" onClick={loadEvents}>Atualizar</button></div><div className="activity-feed">{events.filter(e=>!filter||[e.email,e.profile?.full_name,e.metadata?.question].join(' ').toLowerCase().includes(filter.toLowerCase())).map(e=><article className="activity-item" key={e.id}><span className="activity-icon">{e.event_type==='tutor_question'?<MessageCircle/>:e.event_type==='lesson_completed'?<CheckCircle2/>:<Activity/>}</span><div><strong>{e.profile?.full_name||e.email||'Aluno'}</strong><small>{activityLabel[e.event_type]||e.event_type} · {fmt(e.created_at)}</small>{e.metadata?.title&&<p>{e.metadata.title}</p>}{e.event_type==='tutor_question'&&e.metadata?.question&&<blockquote className="student-question">“{e.metadata.question}”</blockquote>}</div></article>)}{events.length===0&&<p className="empty">Ainda não há eventos registrados. Conforme os alunos navegam, estudam e perguntam à IA, a atividade aparece aqui.</p>}</div></div>}
    {tab==='tickets'&&<div className="admin-ticket-layout"><div className="panel"><div className="panel-title"><div><span className="eyebrow">CENTRAL DE AJUDA</span><h2>Solicitações dos alunos</h2></div><button className="outline-button" onClick={loadTickets}>Atualizar</button></div><div className="ticket-list">{tickets.map(t=><button className={selectedTicket?.id===t.id?'ticket-row selected':'ticket-row'} key={t.id} onClick={()=>{setSelectedTicket(t);setReply(t.admin_reply||'');setTicketStatus(t.status)}}><strong>{t.subject}</strong><small>{t.profile?.full_name||t.email} · {fmt(t.created_at)}</small><span className={'status-pill '+t.status}>{t.status}</span></button>)}{tickets.length===0&&<p className="empty">Nenhuma solicitação recebida ainda.</p>}</div></div><div className="panel">{selectedTicket?<><span className="eyebrow">ATENDER SOLICITAÇÃO</span><h2>{selectedTicket.subject}</h2><p><strong>{selectedTicket.profile?.full_name||'Aluno'}</strong> · {selectedTicket.email}</p><div className="ticket-message">{selectedTicket.message}</div><label>Status<select value={ticketStatus} onChange={e=>setTicketStatus(e.target.value)}><option value="new">Novo</option><option value="in_progress">Em atendimento</option><option value="waiting_user">Aguardando aluno</option><option value="resolved">Resolvido</option><option value="closed">Fechado</option></select></label><form className="admin-form" onSubmit={answerTicket}><label>Resposta do administrador<textarea rows="6" value={reply} onChange={e=>setReply(e.target.value)} placeholder="Escreva a orientação para o aluno…"/></label><button className="button" disabled={busy}>{busy?'Salvando…':'Salvar resposta'}</button></form><a className="support-wa-link" href={'https://wa.me/'+SUPPORT_WHATSAPP+'?text='+encodeURIComponent('Olá, sou do suporte AZELF. Sobre: '+selectedTicket.subject)} target="_blank" rel="noreferrer">Abrir WhatsApp <ExternalLink size={14}/></a></>:<div className="empty ticket-empty"><Headphones size={30}/><strong>Selecione uma solicitação</strong><p>Leia a mensagem do aluno e responda por aqui. A resposta fica registrada no histórico do ticket.</p></div>}</div></div>}
    {tab==='projects'&&<div className="admin-ticket-layout"><div className="panel"><div className="panel-title"><div><span className="eyebrow">PORTFÓLIO DOS ALUNOS</span><h2>Entregas para revisar</h2></div><button className="outline-button" onClick={loadProjects}>Atualizar</button></div><div className="ticket-list">{projects.map(p=><button className={selectedProject?.id===p.id?'ticket-row selected':'ticket-row'} key={p.id} onClick={()=>{setSelectedProject(p);setProjectFeedback(p.mentor_feedback||'');setProjectStatus(p.status==='submitted'?'reviewed':p.status)}}><strong>{p.title}</strong><small>{p.profile?.full_name||p.email} · {p.area} · {fmt(p.submitted_at||p.created_at)}</small><span className={'status-pill '+p.status}>{p.status}</span></button>)}{projects.length===0&&<p className="empty">Nenhuma entrega enviada. Quando o aluno submeter o trabalho dentro de uma aula, ela aparece aqui.</p>}</div></div><div className="panel">{selectedProject?<><span className="eyebrow">REVISÃO DE PROJETO</span><h2>{selectedProject.title}</h2><p><strong>{selectedProject.profile?.full_name||'Aluno'}</strong> · {selectedProject.email}</p><p className="ticket-message">{selectedProject.description}</p>{selectedProject.deliverable_url&&<a className="support-wa-link" href={selectedProject.deliverable_url} target="_blank" rel="noreferrer">Abrir entrega <ExternalLink size={14}/></a>}<form className="admin-form" onSubmit={reviewProject}><label>Status da avaliação<select value={projectStatus} onChange={e=>setProjectStatus(e.target.value)}><option value="reviewed">Revisado</option><option value="needs_changes">Precisa de ajustes</option><option value="submitted">Manter como enviado</option></select></label><label>Feedback para o aluno<textarea rows="7" value={projectFeedback} onChange={e=>setProjectFeedback(e.target.value)} placeholder="O que ficou bom? O que falta? Qual o próximo passo recomendado?"/></label><button className="button" disabled={busy}>Salvar feedback</button></form></>:<div className="empty ticket-empty"><ClipboardList size={30}/><strong>Selecione um projeto</strong><p>Revise a entrega, dê orientação específica e ajude o aluno a melhorar a próxima versão.</p></div>}</div></div>}
    {tab==='codes'&&<div className="admin-code-layout"><div className="panel"><h2>Gerar convite de acesso</h2><p>Cada aluno recebe um código único vinculado ao e-mail dele. Sem código válido, não consegue concluir o cadastro.</p><form onSubmit={generate} className="admin-form"><label>E-mail do comprador/aluno<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="cliente@email.com"/></label><label>Identificação (opcional)<input value={label} onChange={e=>setLabel(e.target.value)} placeholder="Nome, pedido ou turma"/></label><label>Validade<select value={days} onChange={e=>setDays(e.target.value)}><option value="7">7 dias</option><option value="30">30 dias</option><option value="60">60 dias</option><option value="90">90 dias</option></select></label><button className="button" disabled={busy}>{busy?'Gerando…':'Gerar convite'}</button></form>{newCode&&<div className="generated-code"><strong>Código gerado — copie e envie ao aluno</strong><code>{newCode}</code><button className="outline-button" onClick={()=>navigator.clipboard?.writeText(newCode)}>Copiar código</button><a className="support-wa-link" href={'https://azelfone.pages.dev/?invite='+encodeURIComponent(newCode)} target="blank" rel="noreferrer" referrerPolicy="no-referrer">Link direto de cadastro <ExternalLink size={14}/></a><a className="support-wa-link" href={'https://wa.me/?text='+encodeURIComponent('Seu convite AZELF: https://azelfone.pages.dev/?invite='+newCode+' · Use o mesmo e-mail que foi vinculado ao convite.')} target="_blank" rel="noreferrer">Enviar convite pelo WhatsApp <Send size={14}/></a></div>}</div><div className="panel"><div className="panel-title"><h2>Histórico de convites</h2><button className="outline-button" onClick={loadCodes}>Atualizar</button></div><div className="admin-list">{codes.map(code=><div className="admin-user" key={code.id}><div><strong>{code.customer_label||'Convite AZELF'}</strong><small>Criado: {fmt(code.created_at)} · Expira: {fmt(code.expires_at)}</small><small>{code.revoked_at?'Revogado':code.redeemed_by?'Utilizado':code.reserved_email?'Em reserva':'Disponível'}{code.reserved_email?' · '+code.reserved_email:''}</small></div>{!code.redeemed_by&&!code.revoked_at&&<button className="danger-button" onClick={()=>revoke(code.id)}>Revogar</button>}</div>)}</div></div></div>}
    {tab==='labs'&&<div className="admin-content-grid">
      <div className="panel"><span className="eyebrow">NOVO LABORATÓRIO</span><h2>Criar um laboratório da AZELF</h2><p>Um laboratório é uma trilha prática com etapas. Crie o projeto aqui; depois adicione as aulas no editor de conteúdo e publique quando estiver pronto.</p><form className="admin-form" onSubmit={createLab}><label>Nome do laboratório<input required minLength="4" value={labTitle} onChange={e=>setLabTitle(e.target.value)} placeholder="Ex.: Robótica com ESP32"/></label><label>O que o aluno vai construir?<textarea required rows="4" value={labDescription} onChange={e=>setLabDescription(e.target.value)} placeholder="Descreva o resultado final, o material necessário e o que será praticado."/></label><button className="button" disabled={busy}>Criar laboratório como rascunho <Blocks size={15}/></button></form></div>
      <div className="panel"><div className="panel-title"><div><span className="eyebrow">LABORATÓRIOS CADASTRADOS</span><h2>Publicação e etapas</h2></div><span className="muted">{courses.filter(c=>/laborat[oó]rio|lab/i.test(c.category||'')).length} itens</span></div><div className="admin-list">{courses.filter(c=>/laborat[oó]rio|lab/i.test(c.category||'')).map(c=><article className="admin-user" key={c.id}><div><strong>{c.title}</strong><small>{lessons.filter(l=>l.course_id===c.id).length} etapas · {c.is_published?'Publicado':'Rascunho'}</small><small>{c.description}</small></div><div className="user-actions"><button className="mini-button" onClick={()=>{setCourseId(c.id);setTab('content')}}>Adicionar etapas</button><button className={c.is_published?'danger-button':'mini-button'} onClick={()=>toggleCoursePublished(c)} disabled={busy}>{c.is_published?'Despublicar':'Publicar'}</button></div></article>)}{courses.filter(c=>/laborat[oó]rio|lab/i.test(c.category||'')).length===0&&<p className="empty">Nenhum laboratório criado pela equipe. Os laboratórios prontos da plataforma já ficam disponíveis na aba Laboratórios do aluno.</p>}</div></div>
    </div>}
    {tab==='content'&&<div className="admin-content-grid"><div className="panel"><span className="eyebrow">NOVA TRILHA</span><h2>Criar módulo de aprendizagem</h2><form className="admin-form" onSubmit={editingCourse?updateCourse:createCourse}><label>Nome do módulo<input required value={courseTitle} onChange={e=>setCourseTitle(e.target.value)} placeholder="Ex.: Automação com IA"/></label><label>Categoria<input required value={courseCategory} onChange={e=>setCourseCategory(e.target.value)} placeholder="Tecnologia, vendas…"/></label><label>Descrição<textarea rows="3" value={courseDescription} onChange={e=>setCourseDescription(e.target.value)} placeholder="Qual transformação o aluno vai conseguir realizar?"/></label><div className="row-actions"><button className="button" disabled={busy}>{editingCourse?'Salvar alterações':'Criar trilha como rascunho'}</button>{editingCourse&&<button type="button" className="outline-button" onClick={()=>{setEditingCourse(null);setCourseTitle('');setCourseDescription('')}}>Cancelar edição</button>}</div></form></div><div className="panel"><span className="eyebrow">NOVA AULA</span><h2>Criar ou editar uma aula</h2><form className="admin-form" onSubmit={editingLesson?updateLesson:createLesson}><label>Trilha<select value={courseId} onChange={e=>setCourseId(e.target.value)}>{courses.map(c=><option key={c.id} value={c.id}>{c.title} {c.is_published?'· Publicada':'· Rascunho'}</option>)}</select></label><label>Título da aula<input required value={lessonTitle} onChange={e=>setLessonTitle(e.target.value)} placeholder="Resultado prático desta aula"/></label><label>Resumo<input value={lessonSummary} onChange={e=>setLessonSummary(e.target.value)} placeholder="O que o aluno vai fazer?"/></label><label>Conteúdo com demonstração, checklist e exercício<textarea rows="9" required value={lessonContent} onChange={e=>setLessonContent(e.target.value)} placeholder={'## Objetivo\n\n## Materiais e pré-requisitos\n\n## Demonstração\n\n## Prática guiada\n\n## Código ou exemplo\n\n## Desafio\n\n## Critério de conclusão'}/></label><label>Duração estimada (minutos)<input type="number" min="5" max="240" value={lessonMinutes} onChange={e=>setLessonMinutes(e.target.value)}/></label><div className="row-actions"><button className="button" disabled={busy}>{editingLesson?'Salvar alterações':'Criar aula como rascunho'}</button>{editingLesson&&<button type="button" className="outline-button" onClick={()=>{setEditingLesson(null);setLessonTitle('');setLessonSummary('');setLessonContent('')}}>Cancelar edição</button>}</div></form></div><div className="panel content-list-panel"><div className="panel-title"><h2>Trilhas e aulas existentes</h2><span className="muted">{courses.length} trilhas · {lessons.length} aulas</span></div>{courses.map(course=><details className="content-course" key={course.id}><summary>{course.title} <span>{lessons.filter(l=>l.course_id===course.id).length} aulas · {course.is_published?'Publicada':'Rascunho'}</span></summary><div className="content-publish-toolbar"><button className="mini-button" onClick={()=>editCourse(course)}>Editar trilha</button><button className={course.is_published?'danger-button':'mini-button'} disabled={busy} onClick={()=>toggleCoursePublished(course)}>{course.is_published?'Despublicar trilha':'Publicar trilha'}</button><button className="danger-button" disabled={busy} onClick={()=>deleteCourse(course)}>Excluir trilha</button></div>{lessons.filter(l=>l.course_id===course.id).map(l=><div className="content-lesson-row" key={l.id}><span><strong>{l.title}</strong><small>{l.summary} · {l.is_published?'Publicado':'Rascunho'}</small></span><div className="user-actions"><button className="mini-button" onClick={()=>editLesson(l)}>Editar aula</button><button className={l.is_published?'danger-button':'mini-button'} disabled={busy} onClick={()=>toggleLessonPublished(l)}>{l.is_published?'Despublicar':'Publicar'}</button><button className="danger-button" disabled={busy} onClick={()=>deleteLesson(l)}>Excluir aula</button></div></div>)}</details>)}</div></div>}
    {tab==='tools'&&<div className="admin-content-grid">
      <div className="panel"><span className="eyebrow">BIBLIOTECA DE FERRAMENTAS</span><h2>{toolId?'Editar ferramenta':'Cadastrar IA ou ferramenta'}</h2><p>Cadastre links oficiais, descreva a finalidade e controle se o item aparece para os alunos. O endereço abre em nova aba.</p><form className="admin-form" onSubmit={saveTool}>
        <label>Nome<input required value={toolName} onChange={e=>setToolName(e.target.value)} placeholder="Ex.: ChatGPT, Cursor, Gamma"/></label>
        <label>Categoria<input required value={toolCategory} onChange={e=>setToolCategory(e.target.value)} placeholder="IA generativa, pesquisa, programação…"/></label>
        <label>Descrição<textarea required rows="3" value={toolDescription} onChange={e=>setToolDescription(e.target.value)} placeholder="O que a ferramenta faz e em qual tarefa ajuda?"/></label>
        <label>Plano/limites<input value={toolAccess} onChange={e=>setToolAccess(e.target.value)} placeholder="Consulte o site oficial"/></label>
        <label>URL oficial<input type="url" required value={toolUrl} onChange={e=>setToolUrl(e.target.value)} placeholder="https://…"/></label>
        <label>Como usar (opcional)<textarea rows="3" value={toolTutorial} onChange={e=>setToolTutorial(e.target.value)} placeholder="Passos iniciais para o aluno…"/></label>
        <label className="toggle-label"><input type="checkbox" checked={toolAdultOnly} onChange={e=>setToolAdultOnly(e.target.checked)}/> Somente para maiores de 18 anos</label>
        <label className="toggle-label"><input type="checkbox" checked={toolPublished} onChange={e=>setToolPublished(e.target.checked)}/> Publicar na biblioteca</label>
        <div className="row-actions"><button className="button" disabled={busy}>{toolId?'Salvar alterações':'Cadastrar ferramenta'}</button>{toolId&&<button type="button" className="outline-button" onClick={resetToolForm}>Cancelar</button>}</div>
      </form></div>
      <div className="panel"><div className="panel-title"><div><span className="eyebrow">CATÁLOGO ADMINISTRÁVEL</span><h2>Ferramentas cadastradas</h2></div><span className="muted">{tools.length} itens</span></div><div className="admin-list">{tools.map(t=><article className="admin-user" key={t.id}><div><strong>{t.name}</strong><small>{t.category} · {t.is_published?'Publicado':'Rascunho'}{t.adult_only?' · 18+':''}</small><small>{t.official_url}</small></div><div className="user-actions"><button className="mini-button" onClick={()=>editTool(t)}>Editar</button><button className={t.is_published?'danger-button':'mini-button'} disabled={busy} onClick={()=>toggleToolPublished(t)}>{t.is_published?'Despublicar':'Publicar'}</button><button className="danger-button" disabled={busy} onClick={()=>deleteTool(t.id)}>Excluir</button></div></article>)}{tools.length===0&&<p className="empty">Nenhuma ferramenta cadastrada.</p>}</div></div>
    </div>}
    {tab==='affiliates'&&<div className="admin-social-grid"><div className="panel"><span className="eyebrow">CATÁLOGO DE PARCEIROS</span><h2>{affiliateId?'Editar recomendação':'Adicionar produto recomendado'}</h2><form className="admin-form" onSubmit={saveAffiliate}><label>Plataforma<select value={affiliatePlatform} onChange={e=>setAffiliatePlatform(e.target.value)}><option value="mercado_livre">Mercado Livre</option><option value="shopee">Shopee</option><option value="amazon">Amazon</option><option value="hotmart">Hotmart</option><option value="other">Outra</option></select></label><label>Nome do produto<input required value={affiliateTitle} onChange={e=>setAffiliateTitle(e.target.value)} placeholder="Nome oficial do produto"/></label><label>Categoria<input value={affiliateCategory} onChange={e=>setAffiliateCategory(e.target.value)} placeholder="Informática, estudo…"/></label><label>Descrição<textarea rows="3" value={affiliateDescription} onChange={e=>setAffiliateDescription(e.target.value)} placeholder="Para quem serve e qual problema resolve?"/></label><label>URL da página do produto<input type="url" required value={affiliateProductUrl} onChange={e=>setAffiliateProductUrl(e.target.value)} placeholder="https://…"/></label><label>Seu link de afiliado<input type="url" value={affiliateUrl} onChange={e=>setAffiliateUrl(e.target.value)} placeholder="Cole aqui o link oficial gerado no programa"/></label><label>Imagem do produto (URL opcional)<input type="url" value={affiliateImageUrl} onChange={e=>setAffiliateImageUrl(e.target.value)} placeholder="https://…"/></label><label>Preço/condição exibida (opcional)<input value={affiliatePrice} onChange={e=>setAffiliatePrice(e.target.value)} placeholder="Ex.: consultar preço no parceiro"/></label><label>Aviso de transparência<textarea rows="2" value={affiliateDisclosure} onChange={e=>setAffiliateDisclosure(e.target.value)}/></label><label className="toggle-label"><input type="checkbox" checked={affiliatePublished} onChange={e=>setAffiliatePublished(e.target.checked)}/> Publicar na página Recomendações</label><div className="row-actions"><button className="button" disabled={busy}>Salvar produto</button>{affiliateId&&<button type="button" className="outline-button" onClick={()=>{setAffiliateId(null);setAffiliateTitle('');setAffiliateDescription('');setAffiliateProductUrl('');setAffiliateUrl('')}}>Novo</button>}</div></form><p className="admin-footnote">Não publique sem confirmar que o link de afiliado está ativo e pertence à conta AZELF. Informe claramente a possibilidade de comissão.</p></div><div className="panel"><div className="panel-title"><h2>Produtos cadastrados</h2><button className="outline-button" onClick={loadAffiliateRows}>Atualizar</button></div><div className="admin-list">{affiliateRows.map(p=><div className="admin-user" key={p.id}><div><strong>{p.title}</strong><small>{p.platform} · {p.category} · {p.is_published?'Publicado':'Rascunho'}</small><small>{p.affiliate_url?'Link de afiliado configurado':'Ainda falta link de afiliado'}</small></div><div className="user-actions"><button className="mini-button" onClick={()=>editAffiliate(p)}>Editar</button><button className="danger-button" onClick={()=>deleteAffiliate(p.id)}>Excluir</button></div></div>)}{affiliateRows.length===0&&<p className="empty">Nenhum produto cadastrado. Quando você enviar o primeiro link de afiliado, incluiremos aqui.</p>}</div></div></div>}
    {tab==='partners'&&<div className="panel"><div className="panel-title"><div><span className="eyebrow">LINKS PESSOAIS DOS ALUNOS</span><h2>Links de afiliado cadastrados</h2></div><button className="outline-button" onClick={loadPartnerLinks}>Atualizar</button></div><p>Esta lista organiza os links declarados pelos alunos. Não mostra vendas nem comissões; esses dados permanecem nos painéis oficiais de cada marketplace.</p><div className="admin-list">{partnerLinks.map(link=><article className="admin-user" key={link.id}><div><strong>{link.product_name}</strong><small>{link.platform} · usuário {link.user_id}</small><a href={link.affiliate_url} target="_blank" rel="sponsored nofollow noopener noreferrer">{link.affiliate_url}</a></div><div className="user-actions"><button className="danger-button" onClick={()=>deletePartnerLink(link.id)}>Remover link</button></div></article>)}{partnerLinks.length===0&&<p className="empty">Nenhum aluno cadastrou links próprios até agora.</p>}</div></div>}
    {tab==='social'&&<div className="admin-social-grid"><div className="panel"><span className="eyebrow">CALENDÁRIO EDITORIAL</span><h2>Planejar publicação</h2><form className="admin-form" onSubmit={savePost}><label>Rede social<select value={platform} onChange={e=>setPlatform(e.target.value)}><option value="instagram">Instagram</option><option value="tiktok">TikTok</option><option value="youtube">YouTube</option><option value="facebook">Facebook</option><option value="linkedin">LinkedIn</option><option value="x">X</option><option value="other">Outra</option></select></label><label>Título/tema<input required value={postTitle} onChange={e=>setPostTitle(e.target.value)} placeholder="Ex.: como funciona uma blockchain"/></label><label>Legenda e roteiro<textarea rows="6" value={caption} onChange={e=>setCaption(e.target.value)} placeholder="Gancho, conteúdo, CTA e aviso de publicidade, se aplicável…"/></label><label>Link do vídeo ou arquivo de mídia<input value={mediaUrl} onChange={e=>setMediaUrl(e.target.value)} placeholder="Link do vídeo que você vai enviar depois"/></label><label>Data planejada<input type="datetime-local" value={postDate} onChange={e=>setPostDate(e.target.value)}/></label><label>Status<select value={postStatus} onChange={e=>setPostStatus(e.target.value)}><option value="draft">Rascunho</option><option value="ready">Pronto para revisão</option><option value="scheduled">Agendado (manual)</option><option value="published">Já publicado</option></select></label>{postStatus==='published'&&<><label>Link publicado<input value={publishedUrl} onChange={e=>setPublishedUrl(e.target.value)} placeholder="URL do post publicado"/></label><div className="social-metrics-input"><strong>Métricas registradas manualmente</strong><div className="metric-input-grid">{[['Visualizações',postViews,setPostViews],['Curtidas',postLikes,setPostLikes],['Comentários',postComments,setPostComments],['Cliques',postClicks,setPostClicks],['Leads',postLeads,setPostLeads]].map(([label,value,setter])=><label key={label}>{label}<input type="number" min="0" value={value} onChange={e=>setter(Number(e.target.value))}/></label>)}</div></div></>}<div className="row-actions"><button className="button" disabled={busy}>{postId?'Salvar alterações':'Salvar no calendário'}</button>{postId&&<button type="button" className="outline-button" onClick={()=>{setPostId(null);setPostTitle('');setCaption('');setMediaUrl('');setPostDate('');setPublishedUrl('');setPostStatus('draft')}}>Novo post</button>}</div></form><p className="admin-footnote">Esta agenda organiza os conteúdos. Ela não publica automaticamente: para isso será necessário conectar as contas oficiais e autorizações/API de cada rede.</p></div><div className="panel"><div className="panel-title"><h2>Fila de publicações</h2><button className="outline-button" onClick={loadPosts}>Atualizar</button></div><div className="admin-list">{posts.map(p=><div className="social-post-row" key={p.id}><div><strong>{p.title}</strong><small>{p.platform.toUpperCase()} · {p.status} · {fmt(p.scheduled_at)}</small>{p.caption&&<p>{p.caption.slice(0,180)}</p>}{p.media_url&&<a href={p.media_url} target="_blank" rel="noreferrer">Abrir mídia <ExternalLink size={12}/></a>}{p.published_url&&<a href={p.published_url} target="_blank" rel="noreferrer">Ver publicação <ExternalLink size={12}/></a>}{p.status==='published'&&<div className="social-metrics"><span>Views: <strong>{p.performance?.views||0}</strong></span><span>Likes: <strong>{p.performance?.likes||0}</strong></span><span>Comentários: <strong>{p.performance?.comments||0}</strong></span><span>Cliques: <strong>{p.performance?.clicks||0}</strong></span><span>Leads: <strong>{p.performance?.leads||0}</strong></span></div>}</div><div className="social-actions"><button className="mini-button" onClick={()=>editPost(p)}>Editar</button><button className="danger-button" onClick={()=>deletePost(p.id)}><Trash2 size={14}/></button></div></div>)}{posts.length===0&&<p className="empty">Nenhum conteúdo planejado. Adicione seu primeiro vídeo ou post.</p>}</div></div></div>}
    {message&&<p className="notice">{message}</p>}
    <p className="admin-footnote">O painel usa autorização administrativa verificada no servidor. Alterações de status, convites, tickets e calendário são registradas no Supabase.</p>
  </section>
}
function ActivityTrend({data=[]}){const max=Math.max(1,...data.map(d=>Math.max(d.activity||0,d.lessons||0,d.questions||0)));const x=i=>28+i*(544/Math.max(1,data.length-1));const y=v=>150-(v/max*118);const line=k=>data.map((d,i)=>x(i)+','+y(d[k]||0)).join(' ');return <div className="activity-chart"><svg viewBox="0 0 590 190" role="img" aria-label="Gráfico de atividade semanal"><line x1="28" y1="150" x2="572" y2="150" className="chart-axis"/><line x1="28" y1="91" x2="572" y2="91" className="chart-gridline"/><line x1="28" y1="32" x2="572" y2="32" className="chart-gridline"/><polyline points={line('activity')} className="chart-line activity-line"/><polyline points={line('lessons')} className="chart-line lessons-line"/><polyline points={line('questions')} className="chart-line questions-line"/>{data.map((d,i)=><text key={d.key||i} x={x(i)} y="177" textAnchor="middle" className="chart-label">{d.label}</text>)}</svg></div>}



function IncomeHub({openCourses,openLabs,openTools,openAffiliates,openChat,onStartCourse}){
  const paths=[
    {title:'Serviços digitais',tag:'MENOR NECESSIDADE DE CAPITAL',description:'Venda uma entrega clara: página de vendas, site simples, edição de vídeo, design, organização de dados ou automação.',deliverable:'Portfólio de 3 amostras + proposta com escopo e preço.',icon:BriefcaseBusiness},
    {title:'Afiliados',tag:'COMISSÃO POR VENDA ATRIBUÍDA',description:'Escolha produtos úteis, gere seu próprio link no programa aprovado, crie conteúdo honesto e acompanhe vendas no painel oficial.',deliverable:'3 links próprios + 3 recomendações transparentes + plano de divulgação.',icon:ShoppingBag},
    {title:'Conteúdo e aquisição',tag:'TRÁFEGO QUALIFICADO',description:'Produza tutoriais, comparações e demonstrações. Meça cliques, leads, conversão e custo por resultado.',deliverable:'Calendário de 7 dias + 3 roteiros + painel simples de métricas.',icon:Video},
    {title:'Produtos digitais',tag:'ATIVO REUTILIZÁVEL',description:'Crie templates, planilhas, e-books ou kits que resolvam uma tarefa específica. Valide com usuários antes de investir em anúncios.',deliverable:'Protótipo testado + instruções + página de apresentação.',icon:BookOpen},
    {title:'Automação para negócios',tag:'SERVIÇO B2B',description:'Mapeie uma tarefa repetitiva, faça um protótipo seguro e ofereça redução de trabalho manual com supervisão humana.',deliverable:'Fluxo documentado + demonstração com dados fictícios + plano de manutenção.',icon:Workflow}
  ]
  return <section className="workspace income-hub">
    <div className="section-heading left"><span className="eyebrow"><Wallet size={14}/> CENTRAL DE RENDA AZELF</span><h1>Aprenda uma habilidade. Construa uma entrega. Valide um mercado.</h1><p>Esta área transforma aprendizado em trabalho demonstrável. Nenhum caminho garante renda: o objetivo é produzir algo útil, testar demanda e medir custos antes de escalar.</p></div>
    <div className="income-principle-grid"><div className="income-principle"><span>01</span><strong>Habilidade</strong><small>Aprenda uma competência que resolve um problema.</small></div><div className="income-principle"><span>02</span><strong>Entrega</strong><small>Construa amostra, produto ou serviço demonstrável.</small></div><div className="income-principle"><span>03</span><strong>Validação</strong><small>Converse com pessoas e teste disposição de compra.</small></div><div className="income-principle"><span>04</span><strong>Economia</strong><small>Calcule margem, tempo, custo e risco.</small></div></div>
    <div className="income-path-grid">{paths.map(path=>{const Icon=path.icon;return <article className="income-path-card" key={path.title}><div className="income-path-icon"><Icon size={22}/></div><span className="eyebrow">{path.tag}</span><h2>{path.title}</h2><p>{path.description}</p><div className="income-deliverable"><strong>Entrega prática</strong><small>{path.deliverable}</small></div></article>})}</div>
    <div className="income-learning panel"><div><span className="eyebrow">TRILHA COMPLETA</span><h2>Renda Digital na Prática</h2><p>8 aulas com tarefas: validar demanda, montar portfólio, encontrar clientes, trabalhar como afiliado com links próprios, criar conteúdo, desenvolver produto digital, automatizar processos e calcular margem.</p></div><button className="button" onClick={onStartCourse}>Abrir curso e começar <ArrowRight size={15}/></button></div>
    <div className="income-affiliate-resources panel"><span className="eyebrow">PROGRAMAS OFICIAIS</span><h2>Comece pelas fontes oficiais</h2><div className="income-resource-row"><div><strong>Mercado Livre — Afiliados e Criadores</strong><small>Consulte elegibilidade, regras de divulgação e gere seus links no portal da sua conta.</small></div><a href="https://www.mercadolivre.com.br/l/afiliados-home" target="_blank" rel="noopener noreferrer">Abrir portal <ExternalLink size={14}/></a></div><div className="income-resource-row"><div><strong>Shopee — Programa de Afiliados</strong><small>Faça a inscrição, aguarde aprovação e gere seus próprios links. Para divisão de comissão via MCN, confirme elegibilidade e regras antes de prometer repasses.</small></div><div className="income-resource-links"><a href="https://shopee.com.br/m/afiliados" target="_blank" rel="noopener noreferrer">Inscrição <ExternalLink size={14}/></a><a href="https://help.shopee.com.br/portal/10/article/124094" target="_blank" rel="noopener noreferrer">Termos <ExternalLink size={14}/></a></div></div><p className="admin-footnote">Links dos marketplaces são independentes da AZELF. Requisitos, aprovação, canais permitidos, atribuição e pagamentos são definidos por cada programa e podem mudar.</p></div>
    <div className="income-shortcuts"><button className="outline-button" onClick={openAffiliates}><ShoppingBag size={16}/> Ver produtos e meus links</button><button className="outline-button" onClick={openLabs}><Blocks size={16}/> Praticar em laboratórios</button><button className="outline-button" onClick={openTools}><BrainCircuit size={16}/> Ferramentas para produzir</button><button className="outline-button" onClick={openChat}><MessageCircle size={16}/> Planejar com Tutor IA</button></div>
  </section>
}

function LearningLab({openCrypto,openPractical,customLabs=[],openCustomLab}){
  const cards=[
    {id:'esp32',number:'LAB 04',title:'ESP32 e Internet das Coisas',category:'ELETRÔNICA · IOT',description:'Aprenda GPIO, LED, botão, sensor analógico, Wi-Fi e monitor serial, com simulação e código Arduino para testar na placa.',icon:Cpu,items:['GPIO e lógica digital','Leitura de sensores','Código Arduino completo'],action:()=>openPractical('esp32'),label:'Abrir laboratório'},
    {id:'pow',number:'LAB 05',title:'Mineração e Proof of Work',category:'CRIPTOGRAFIA · SHA-256',description:'Resolva um desafio de hash com nonce e dificuldade configurável. Veja por que mineração exige trabalho computacional.',icon:Blocks,items:['Hash SHA-256','Nonce e dificuldade','Prova local de trabalho'],action:()=>openPractical('pow'),label:'Executar simulação'},
    {id:'web',number:'LAB 06',title:'Estúdio de programação web',category:'HTML · CSS · JAVASCRIPT',description:'Edite um pequeno projeto e veja a prévia rodando em um ambiente isolado do restante da plataforma.',icon:Code2,items:['Estrutura HTML','Estilo CSS','Interação JavaScript'],action:()=>openPractical('web'),label:'Abrir editor'},
    {id:'prompts',number:'LAB 07',title:'Estúdio de prompts',category:'IA · ENGENHARIA DE PROMPTS',description:'Monte uma instrução estruturada, compare contexto e formato e copie um prompt pronto para testar em um assistente.',icon:BrainCircuit,items:['Objetivo e contexto','Formato e critérios','Prompt copiável'],action:()=>openPractical('prompts'),label:'Montar prompt'},
    {id:'marketing',number:'LAB 08',title:'Marketing e funil de conversão',category:'AQUISIÇÃO · VENDAS',description:'Simule orçamento, impressões, cliques, leads, conversões e margem para entender o resultado de uma campanha.',icon:TrendingUp,items:['CTR e taxa de lead','Conversão em vendas','ROAS e ROI estimados'],action:()=>openPractical('marketing'),label:'Simular campanha'},
    {id:'automation',number:'LAB 09',title:'Automação de processos',category:'FLUXOS · LÓGICA',description:'Desenhe uma regra evento-condição-ação e teste um fluxo de aprovação sem conectar contas ou disparar mensagens reais.',icon:Workflow,items:['Evento e condição','Ação automatizada','Histórico da simulação'],action:()=>openPractical('automation'),label:'Testar fluxo'}
  ]
  return <section className="workspace lab-page">
    <div className="section-heading left"><span className="eyebrow">APRENDER FAZENDO</span><h1>Laboratórios AZELF</h1><p>Ambientes interativos para testar código, raciocínio, gráficos, operações fictícias e decisões de negócio. Cada laboratório tem uma tarefa executável e uma explicação do resultado.</p></div>
    <div className="lab-grid">
      <article className="lab-card crypto-lab-card"><div className="lab-card-visual"><div className="lab-token-orbit"><Blocks size={48}/><span className="token-dot dot-a"/><span className="token-dot dot-b"/><span className="token-dot dot-c"/></div><span className="lab-label">BLOCKCHAIN · SIMULAÇÃO</span></div><div className="lab-card-body"><span className="eyebrow">LAB 01</span><h2>Crie um token e monte uma blockchain</h2><p>Configure nome, símbolo e oferta fictícia; envie uma transação simulada; agrupe-a em um bloco e acompanhe o encadeamento por SHA-256.</p><ul><li>Token e oferta</li><li>Carteira e transações fictícias</li><li>Blocos, nonce e hash</li></ul><button className="button" onClick={()=>openCrypto('chain')}>Entrar no laboratório <ArrowRight size={16}/></button></div></article>
      <article className="lab-card market-lab-card"><div className="lab-card-visual"><div className="market-lines"><svg viewBox="0 0 360 150"><polyline points="0,118 35,95 70,104 105,68 140,78 175,42 210,60 245,30 280,48 320,12 360,25" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/><polyline points="0,118 35,95 70,104 105,68 140,78 175,42 210,60 245,30 280,48 320,12 360,25 360,150 0,150" fill="currentColor" opacity=".08"/></svg></div><span className="lab-label">MERCADO · PAPER TRADING</span></div><div className="lab-card-body"><span className="eyebrow">LAB 02</span><h2>Gráficos, risco e operações simuladas</h2><p>Selecione pontos de uma série hipotética, altere o preço de referência e veja posição, saldo, taxa e risco em um simulador.</p><ul><li>Gráficos selecionáveis</li><li>Compra e venda de demonstração</li><li>Exposição e custo de operação</li></ul><button className="outline-button" onClick={()=>openCrypto('market')}>Abrir gráfico e trading <ArrowRight size={16}/></button></div></article>
      <article className="lab-card business-lab-card"><div className="lab-card-visual"><div className="profit-stack"><span>RECEITA</span><strong>− CUSTOS</strong><em>= MARGEM</em></div><span className="lab-label">NEGÓCIOS · UNIT ECONOMICS</span></div><div className="lab-card-body"><span className="eyebrow">LAB 03</span><h2>Monte uma oferta e calcule o lucro</h2><p>Simule preço, custo variável, custos fixos e volume. Veja faturamento, margem de contribuição, lucro, ROI e ponto de equilíbrio.</p><ul><li>Preço e custo unitário</li><li>Margem e lucro operacional</li><li>ROI e vendas necessárias</li></ul><button className="outline-button" onClick={()=>openCrypto('business')}>Abrir simulador de negócio <ArrowRight size={16}/></button></div></article>
      {cards.map(card=>{const Icon=card.icon;return <article className="lab-card practical-lab-card" key={card.id}><div className="lab-card-visual"><div className="practical-lab-icon"><Icon size={42}/></div><span className="lab-label">{card.category}</span></div><div className="lab-card-body"><span className="eyebrow">{card.number}</span><h2>{card.title}</h2><p>{card.description}</p><ul>{card.items.map(item=><li key={item}>{item}</li>)}</ul><button className="outline-button" onClick={card.action}>{card.label} <ArrowRight size={16}/></button></div></article>})}
    </div>
    {customLabs.length>0&&<div className="panel custom-labs-panel"><div className="panel-title"><div><span className="eyebrow">CRIADOS PELA EQUIPE</span><h2>Laboratórios da comunidade AZELF</h2></div><span className="status-pill active">{customLabs.length} publicados</span></div><div className="custom-labs-list">{customLabs.map(course=><button className="custom-lab-row" key={course.id} onClick={()=>openCustomLab(course)}><span className="course-icon"><Blocks/></span><span><strong>{course.title}</strong><small>{course.description||'Laboratório prático criado pela equipe.'}</small></span><ChevronRight/></button>)}</div></div>}
    <p className="lab-disclaimer">Todos os simuladores usam dados locais ou hipotéticos. Não enviam ordens, não publicam contratos, não acessam carteiras e não se conectam a placas físicas automaticamente. Para usar ESP32 real, siga as instruções de hardware e segurança.</p>
  </section>
}

function copyLabText(value,setNotice){
  if(!navigator.clipboard?.writeText){setNotice('Seu navegador não liberou a área de transferência. Selecione e copie o conteúdo manualmente.');return}
  navigator.clipboard.writeText(value).then(()=>setNotice('Conteúdo copiado.')).catch(()=>setNotice('Não foi possível copiar automaticamente. Copie manualmente.'))
}

